/** What the TLS handshake told us about the certificate being served. */
export type ServedIdentity = {
  notAfter: Date;
  coversDomain: boolean;
  /** Issuer common name, e.g. "R11", "E5", "WE1". "" when unreadable. */
  issuerCN: string;
  /** Issuer organisation, e.g. "Let's Encrypt", "Google Trust Services". "" when unreadable. */
  issuerO: string;
  /** `socket.authorized` — would a browser trust this chain? */
  authorized: boolean;
  /** `socket.authorizationError`, "" when authorized. */
  authorizationError: string;
};

/**
 * Is the certificate on the wire plausibly from the issuer we use for this row?
 *
 * Returns true when we cannot tell. A false mismatch is as misleading as a
 * missed one (the same reasoning as `majorVersion` in worker/migrate-real.ts):
 * refusing to adopt an expiry we have no grounds to doubt would strand rows on
 * stale dates, which is the very failure this is meant to prevent.
 */
export function issuerMatchesOurs(
  served: Pick<ServedIdentity, "issuerCN" | "issuerO">,
  ourIssuer: string
): boolean {
  const cn = String(served.issuerCN ?? "").trim();
  const o = String(served.issuerO ?? "").trim();
  if (!cn && !o) return true; // nothing to judge
  if (String(ourIssuer ?? "").toLowerCase() !== "letsencrypt") return true; // we only know LE

  if (/let'?s encrypt/i.test(o) || /let'?s encrypt/i.test(cn)) return true;
  // Let's Encrypt's intermediates are a single letter plus digits: R3, R10, R11,
  // E1, E5… Matching the shape as well as the name keeps this working when they
  // rotate to a name we have not seen.
  if (/^[RE]\d{1,3}$/.test(cn)) return true;
  // The staging hierarchy, so a staging certificate is not mistaken for a CDN's.
  if (/\(STAGING\)/i.test(o) || /\(STAGING\)/i.test(cn)) return true;
  return false;
}

export type ServedVerdict = {
