 * Ordered by what the customer loses: a chain a browser will reject outranks a
 * date we might have adopted from the wrong certificate, which outranks an
 * ordinary expiry.
 */
export function servedCertVerdict(opts: {
  domain: string;
  served: ServedIdentity;
  /** The expiry we last observed for OUR certificate. */
  recordedExpiry: Date | null;
  /** The row's `issuer` column. */
  ourIssuer: string;
  now: number;
}): ServedVerdict {
  const { domain, served, recordedExpiry, now } = opts;

  if (!served.coversDomain) {
    return {
      status: null,
      adoptExpiry: false,
      note:
        `Port 443 on ${domain} is serving a certificate issued for a different hostname, so visitors get ` +
        `NET::ERR_CERT_COMMON_NAME_INVALID. Check which certificate your web server is configured to use.`,
    };
  }

  const expiredOnWire = served.notAfter.getTime() <= now;

  if (!served.authorized && !expiredOnWire) {
    // A self-signed or broken-chain certificate covering the right name used to
    // read as ACTIVE, because only the name and the date were checked. Every
    // visitor sees a full-page browser warning.
    return {
      status: null,
      adoptExpiry: false,
      note:
        `The certificate served for ${domain} covers the right hostname but is NOT trusted by browsers ` +
        `(${served.authorizationError || "chain verification failed"}), so visitors still get a security ` +
        `warning. This is not an active certificate. Check that your web server is serving the full chain ` +
        `(fullchain.pem, not cert.pem).`,
    };
  }

  const ours = issuerMatchesOurs(served, opts.ourIssuer);
  const differentDate =
    recordedExpiry !== null && Math.abs(served.notAfter.getTime() - recordedExpiry.getTime()) > DAY_MS;

  if (!ours && differentDate) {
    // The M7 #5 case. Adopting this date is what let the origin certificate die.
    const oursValid = recordedExpiry !== null && recordedExpiry.getTime() > now;
    const issuer = served.issuerO || served.issuerCN || "an unknown issuer";
    return {
      status: oursValid ? "ACTIVE" : "EXPIRED",
      adoptExpiry: false,
      note:
        `The certificate served for ${domain} was issued by ${issuer} and expires ` +
        `${served.notAfter.toISOString().slice(0, 10)} — it is NOT the certificate we issued, which expires ` +
        `${recordedExpiry!.toISOString().slice(0, 10)}. That normally means ${domain} is behind a CDN or ` +
        `proxy (Cloudflare, Fastly) terminating TLS at its edge. We are keeping our own expiry date rather ` +
        `than the edge's, because yours is the one that has to be renewed — if it lapses, the CDN can no ` +
        `longer reach your origin over HTTPS.`,
    };
  }

  if (expiredOnWire) {
    return {
      status: "EXPIRED",
      adoptExpiry: ours,
      note:
        `The certificate being served for ${domain} expired on ${served.notAfter.toISOString().slice(0, 10)}. ` +
        `Visitors see a browser security warning until a new one is installed.`,
    };
  }

  return { status: "ACTIVE", adoptExpiry: ours, note: null };
