// THROWAWAY seed for the SSL overhaul screenshots. Never committed. Targets
// nxeon_agt_ssl only (refuses any other DB).
import { PrismaClient } from "@prisma/client";
import { SignJWT } from "jose";
import { writeFileSync } from "node:fs";

const url = process.env.DATABASE_URL ?? "";
if (!url.endsWith("/nxeon_agt_ssl")) throw new Error("refusing: not the throwaway DB");
const db = new PrismaClient();
const D = 86_400_000;
const now = Date.now();
const at = (ms: number) => new Date(now + ms);

async function main() {
  await db.job.deleteMany({});
  await db.sslCertificate.deleteMany({});
  await db.server.deleteMany({});
  await db.user.deleteMany({ where: { email: { endsWith: "@ssl.test" } } });

  const plan = await db.plan.upsert({ where: { slug: "vps-2" }, update: {}, create: { slug: "vps-2", name: "VPS 2", cpuCores: 2, ramMB: 4096, diskGB: 80, priceCents: 1200 } });
  const os = await db.osTemplate.upsert({ where: { slug: "ubuntu-24" }, update: {}, create: { slug: "ubuntu-24", name: "Ubuntu", vmid: 9000 } });
  const node = await db.node.upsert({ where: { name: "sgp-1" }, update: {}, create: { name: "sgp-1", pveNode: "pve", apiUrl: "https://203.0.113.10:8006", tokenId: "x", tokenSecret: "x", publicIp: "203.0.113.10" } });

  const mk = (email: string, name: string) => db.user.create({ data: { email, name, passwordHash: "x", emailVerified: true } as any });
  const full = await mk("full@ssl.test", "Avery Chen");
  const empty = await mk("empty@ssl.test", "Sam Ortiz");
  const none = await mk("none@ssl.test", "Riley Park");

  const srv = (userId: string, hostname: string, status = "RUNNING") =>
    db.server.create({ data: { name: hostname, hostname, userId, planId: plan.id, osTemplateId: os.id, status: status as any, nodeId: node.id, sshPort: 20001, ipAddress: null } as any });
  const web = await srv(full.id, "web-01.northwind");
  const api = await srv(full.id, "api-02.northwind");
  await srv(empty.id, "studio-box");
  // Someone else's server holding the worker slot (queue explanation).
  const other = await srv(none.id, "other-tenant-box");

  const cert = (d: any) => db.sslCertificate.create({ data: { userId: full.id, issuer: "letsencrypt", ...d } });

  const c1 = await cert({ domain: "app.northwind.io", serverId: web.id, status: "ACTIVE", issuedAt: at(-16 * D), expiresAt: at(74 * D), createdAt: at(-200 * D) });
  await cert({ domain: "shop.northwind.io", serverId: web.id, status: "ACTIVE", issuedAt: at(-78 * D), expiresAt: at(12 * D), createdAt: at(-78 * D) });
  await cert({ domain: "api.northwind.io", serverId: api.id, status: "ACTIVE", issuedAt: at(-3 * D), expiresAt: at(87 * D), createdAt: at(-3 * D),
    lastError: "The certificate exists, but nothing is serving it for https://api.northwind.io — port 443 refused the connection. certbot obtains the certificate in standalone mode; it does not install it into your web server. Point your TLS config at /etc/letsencrypt/live/api.northwind.io/fullchain.pem and privkey.pem, then reload it." });
  await cert({ domain: "blog.northwind.io", serverId: web.id, status: "FAILED", createdAt: at(-1 * D),
    lastError: "certbot failed: Certbot failed to authenticate some domains (authenticator: standalone). The Certificate Authority reported these problems:\n  Domain: blog.northwind.io\n  Type:   dns\n  Detail: DNS problem: NXDOMAIN looking up A for blog.northwind.io - check that a DNS record exists for this domain" });
  const pend = await cert({ domain: "staging.northwind.io", serverId: api.id, status: "PENDING", createdAt: at(-6 * 60_000) });
  await cert({ domain: "old.northwind.io", serverId: web.id, status: "EXPIRED", autoRenew: false, issuedAt: at(-93 * D), expiresAt: at(-3 * D), createdAt: at(-93 * D) });
  await cert({ domain: "legacy.northwind.io", serverId: "deleted-server-id", status: "ACTIVE", issuedAt: at(-60 * D), expiresAt: at(9 * D), createdAt: at(-150 * D),
    lastError: "This certificate's server was deleted, so it cannot be renewed. Delete this record, or issue a new certificate on a server that exists." });

  // Renewal history for app.northwind.io.
  const hist = [
    { ago: 200, step: "certificate issued", status: "DONE", renewal: false },
    { ago: 106, step: "failed at the certbot/ACME step", status: "DONE", renewal: true, error: null },
    { ago: 105, step: "certificate issued", status: "DONE", renewal: true },
    { ago: 16, step: "certificate issued", status: "DONE", renewal: true },
  ];
  for (const h of hist) {
    await db.job.create({ data: { type: "SSL_ISSUE", status: h.status as any, step: h.step, serverId: web.id, createdAt: at(-h.ago * D), finishedAt: at(-h.ago * D + 90_000), payload: { certId: c1.id, domain: c1.domain, renewal: h.renewal } } });
  }
  // A running migration on another tenant + queued work ahead of our pending request.
  await db.job.create({ data: { type: "MIGRATE" as any, status: "RUNNING", serverId: other.id, createdAt: at(-40 * 60_000) } });
  await db.job.create({ data: { type: "BACKUP_CREATE" as any, status: "QUEUED", serverId: other.id, createdAt: at(-9 * 60_000) } });
  await db.job.create({ data: { type: "SSL_ISSUE", status: "QUEUED", serverId: api.id, createdAt: at(-6 * 60_000), payload: { certId: pend.id, domain: pend.domain } } });

  const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
  const tok: Record<string, string> = {};
  for (const [k, u] of Object.entries({ full, empty, none })) {
    tok[k] = await new SignJWT({ sub: u.id, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("7d").sign(secret);
  }
  writeFileSync(process.argv[2] ?? "/tmp/ssl-tokens.json", JSON.stringify({ ...tok, certId: c1.id }));
  console.log("seeded", c1.id);
}
main().finally(() => db.$disconnect());

