// usage: node shot.mjs <prefix> <path> <tokenKey> [more paths...]
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
const require = createRequire("/opt/nxeon/node_modules/");
const { chromium } = require("playwright");

const [, , prefix, tokenKey, ...paths] = process.argv;
const tok = JSON.parse(readFileSync(new URL("./ssl-tokens.json", import.meta.url)));
const BASE = process.env.BASE ?? "http://localhost:3077";
const OUT = "/root/agent-notes/ssl-overhaul";
const browser = await chromium.launch();
const views = [
  { tag: "desktop", width: 1440, height: 1000, mobile: false },
  { tag: "mobile", width: 390, height: 844, mobile: true },
];
for (const p of paths) {
  const resolved = p.replace("{certId}", tok.certId);
  for (const v of views) {
    for (const theme of ["dark", "light"]) {
      const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, deviceScaleFactor: 2, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme, reducedMotion: "reduce" });
      await ctx.addCookies([{ name: "nx_agt_ssl", value: tok[tokenKey], url: BASE }, { name: "nx_theme", value: theme, url: BASE }, { name: "nxeon_tour_dismissed", value: "1", url: BASE }]);
      const page = await ctx.newPage();
      await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("theme", t); localStorage.setItem("nx_tour_done", "1"); } catch {} }, theme);
      const errs = [];
      page.on("pageerror", (e) => errs.push(String(e)));
      await page.goto(BASE + resolved, { waitUntil: "networkidle", timeout: 120000 }).catch((e) => errs.push("goto " + e));
      await page.evaluate((t) => document.documentElement.setAttribute("data-theme", t), theme);
      await page.waitForTimeout(1500);
      const name = `${OUT}/${prefix}-${resolved.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "").replace(tok.certId, "id")}-${v.tag}-${theme}.png`;
      await page.screenshot({ path: name, fullPage: true });
      console.log(name, errs.length ? "ERR " + errs.join(" | ").slice(0, 400) : "");
      await ctx.close();
    }
  }
}
await browser.close();

