import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

// Regression guard for the 2026-10-05 incident: a certificate row pointing at a deleted server made
// prisma.job.create throw P2003 inside sslRenewalSweep, aborting the sweep for every certificate behind it.
const src = readFileSync(join(__dirname, "..", "worker", "ssl.ts"), "utf8");
const sweep = src.slice(src.indexOf("export async function sslRenewalSweep"));

test("the renewal sweep checks the server exists before queuing a job for it", () => {
  const guard = sweep.indexOf("db.server.findUnique({ where: { id: fresh.serverId }");
  const create = sweep.indexOf('type: "SSL_ISSUE"');
  assert.ok(guard > 0, "server-exists guard is missing");
  assert.ok(create > guard, "the guard must come BEFORE the job is created");
  assert.match(sweep, /if \(!serverExists\)[\s\S]{0,400}continue;/);
});

test("a failure queuing one renewal does not abort the sweep", () => {
  assert.match(sweep, /try \{\s*await db\.job\.create\(\{[\s\S]{0,400}\} catch \(e\) \{[\s\S]{0,300}continue;/);
});

test("the note shown on an orphaned certificate says what to do", () => {
  assert.match(src, /export const SERVER_GONE_NOTE =\s*"This certificate's server was deleted/);
});
