async function probeServedCertificate(domain: string): Promise<ServedCert> {
  // SSRF guard: resolve the domain and REFUSE if it points at any internal /
  // reserved address. A customer owns their domain's public DNS after issuance
  // and could re-point it at 127.0.0.1 / 169.254.169.254 / RFC1918, turning this
  // probe into an internal :443 scanner whose result leaks back via the row's
  // lastError. We connect to the VETTED IP (not the hostname) so DNS can't rebind
  // between check and connect, while keeping SNI/servername = domain so the right
  // certificate is still validated. One generic reason for all internal targets,
  // so no connectivity oracle survives (audit 2026-08-01).
  let safeIp: string;
  try {
    const addrs = await dnsLookup(domain, { all: true });
    if (!addrs.length || addrs.some((r) => isDisallowedProbeIp(r.address))) {
      return { ok: false, reason: "the domain does not resolve to a public address" };
    }
    safeIp = addrs[0].address;
  } catch {
    return { ok: false, reason: "the domain does not resolve in DNS" };
  }

  return new Promise((resolve) => {
    let settled = false;
    let socket: ReturnType<typeof tlsConnect> | null = null;
    const done = (r: ServedCert) => {
      if (settled) return;
      settled = true;
      try {
        socket?.destroy();
      } catch {
        /* best effort */
      }
      resolve(r);
    };

