/**
 * Pure presentation logic for the customer SSL pages (/dashboard/ssl, /new, /[id]).
 *
 * Nothing in here invents a fact. Every state is derived from a value the
 * platform OBSERVED — `expiresAt` is the notAfter read off the certificate
 * (openssl at issuance, then a TLS read-back of :443 in worker/ssl.ts's sweep),
 * `lastError` is what the worker or the sweep wrote — and when a value is
 * missing the state says "unverified" rather than guessing.
 *
 * Kept free of React, Prisma and node built-ins so test/ssl-status.test.ts can
 * exercise every branch directly.
 */

export const DAY_MS = 86_400_000;

/**
 * worker/ssl.ts renews from 21 days before expiry (RENEW_LEAD_MS). Duplicated
 * here rather than imported because worker/ssl.ts pulls in ssh2, which must
 * never reach the Next bundle. Keep the two in sync.
 */
export const RENEW_LEAD_DAYS = 21;

/** Prefix of worker/ssl.ts's SERVER_GONE_NOTE (also not importable, same reason). */
const SERVER_GONE_PREFIX = "This certificate's server was deleted";
/** Prefix of worker/ssl.ts's RENEWAL_PAUSED_PREFIX. */
const RENEWAL_PAUSED_PREFIX = "Automatic renewal is paused";

export type CertState =
  /** Observed expiry in the future, nothing flagged. */
  | "active"
  /** Active, but inside the renewal window (≤ 21 days left). */
  | "expiring"
  /** The certificate exists but something about it is wrong (not served, wrong name, server gone…). */
  | "attention"
  /** ACTIVE row with no observed expiry — we cannot confirm it is valid. */
  | "unverified"
  | "expired"
  | "failed"
  /** Waiting in the platform queue (or orphaned — see `stalled`). */
  | "pending"
  | "issuing";

/** The filter bucket a state belongs to on the list page. */
export type CertGroup = "healthy" | "expiring" | "attention" | "progress";

export type CertInput = {
  status: string;
  issuedAt: string | null;
  expiresAt: string | null;
  lastError: string | null;
  autoRenew: boolean;
  /** "none" = PENDING row with no job attached at all. */
  queueState?: "running" | "queued" | "none" | null;
};

export type CertView = {
  state: CertState;
  group: CertGroup;
  /** Short status label for a chip. */
  label: string;
  /** Tone for colour: maps to the portal's mint / amber / rose / blue / violet. */
  tone: "mint" | "amber" | "rose" | "blue" | "violet";
  /** Whole days until the OBSERVED expiry (negative = past). null = no observed expiry. */
  daysLeft: number | null;
  /**
   * Remaining share of this certificate's real lifetime, 0..1 — only when BOTH
   * the issue date and the expiry were observed. Never a computed 90-day guess.
   */
  lifeLeft: number | null;
  /** When the automatic renewal window opens (expiry − 21 days), if it applies. */
  renewWindowOpensAt: string | null;
  /** True for a PENDING row nothing is working on. */
  stalled: boolean;
};

export function daysUntil(iso: string | null, now: number): number | null {
  if (!iso) return null;
  const t = new Date(iso).getTime();
  if (Number.isNaN(t)) return null;
  return Math.floor((t - now) / DAY_MS);
}

/** Decide what a certificate row honestly is right now. */
export function certView(c: CertInput, now: number = Date.now()): CertView {
  const daysLeft = daysUntil(c.expiresAt, now);
  let lifeLeft: number | null = null;
  if (c.issuedAt && c.expiresAt) {
    const a = new Date(c.issuedAt).getTime();
    const b = new Date(c.expiresAt).getTime();
    if (b > a) lifeLeft = Math.max(0, Math.min(1, (b - now) / (b - a)));
  }
  const renewWindowOpensAt =
    c.expiresAt && c.autoRenew && (c.status === "ACTIVE" || c.status === "ISSUING")
      ? new Date(new Date(c.expiresAt).getTime() - RENEW_LEAD_DAYS * DAY_MS).toISOString()
      : null;
  const base = { daysLeft, lifeLeft, renewWindowOpensAt, stalled: false };

  switch (c.status) {
    case "PENDING": {
      const stalled = c.queueState === "none";
      return { ...base, stalled, state: "pending", group: "progress",
        label: stalled ? "Not started" : "Queued", tone: stalled ? "amber" : "blue" };
    }
    case "ISSUING":
      return { ...base, state: "issuing", group: "progress", label: "Issuing", tone: "blue" };
    case "EXPIRED":
      return { ...base, state: "expired", group: "attention", label: "Expired", tone: "rose" };
    case "FAILED":
      return { ...base, state: "failed", group: "attention", label: "Failed", tone: "rose" };
    case "ACTIVE": {
      if (c.expiresAt === null || daysLeft === null) {
        return { ...base, state: "unverified", group: "attention", label: "Unverified", tone: "amber" };
      }
      // The sweep marks lapsed rows EXPIRED every 30 minutes; between passes the
      // row can still say ACTIVE with a date in the past. Say what the date says.
      if (new Date(c.expiresAt).getTime() <= now) {
        return { ...base, state: "expired", group: "attention", label: "Expired", tone: "rose" };
      }
      if (c.lastError) {
        return { ...base, state: "attention", group: "attention", label: "Needs attention", tone: "amber" };
      }
      if (daysLeft <= RENEW_LEAD_DAYS) {
        return { ...base, state: "expiring", group: "expiring", label: daysLeft <= 7 ? "Expires soon" : "Renewing soon", tone: "amber" };
      }
      return { ...base, state: "active", group: "healthy", label: "Active", tone: "mint" };
    }
    default:
      return { ...base, state: "failed", group: "attention", label: c.status.toLowerCase(), tone: "rose" };
  }
}

/** "in 74 days" / "today" / "3 days ago" — for an observed date. */
export function relativeDays(days: number): string {
  if (days === 0) return "today";
  if (days === 1) return "tomorrow";
  if (days === -1) return "yesterday";
  return days > 0 ? `in ${days} days` : `${Math.abs(days)} days ago`;
}

// ---------------------------------------------------------------------------
// Error explanations
// ---------------------------------------------------------------------------

export type ErrorKind =
  | "server-gone"
  | "renewal-paused"
  | "issuance-off"
  | "rate-limit"
  | "dns"
  | "caa"
  | "port80-blocked"
  | "wrong-target"
  | "port80-busy"
  | "certbot-install"
  | "server-unreachable"
  | "not-installed"
  | "wrong-name"
  | "untrusted"
  | "cdn"
  | "served-expired"
  | "stalled"
  | "expiry-unreadable"
  | "unchanged"
  | "unknown";

export type ErrorExplanation = {
  kind: ErrorKind;
  /** One plain-language line: what happened. */
  title: string;
  /** Why, in a sentence or two, with no jargon the customer has to look up. */
  why: string;
  /** Concrete steps, in order. */
  fixes: string[];
  /** Whether "Renew now"/retry is the right next move once the fixes are done. */
  retryHelps: boolean;
};

/**
 * Turn a raw `lastError` (worker, sweep or certbot text) into something a
 * customer can act on. The raw text is still shown, under "technical details" —
 * this is a reading aid, never a replacement.
 *
 * Order matters: the worker wraps certbot output ("Renewal failed: certbot
 * failed: …"), so the most specific causes are tested first.
 */
export function explainSslError(raw: string | null, domain = "your domain"): ErrorExplanation | null {
  if (!raw) return null;
  const t = raw;

  if (t.startsWith(SERVER_GONE_PREFIX)) {
    return {
      kind: "server-gone",
      title: "The server this certificate lived on was deleted",
      why: "There is no machine left to renew it on, so it will expire on its own.",
      fixes: [
        "Delete this record.",
        `Issue a new certificate for ${domain} on a server you still have.`,
      ],
      retryHelps: false,
    };
  }
  if (t.startsWith(RENEWAL_PAUSED_PREFIX)) {
    return {
      kind: "renewal-paused",
      title: "Automatic renewal is paused to protect your weekly limit",
      why: "Recent attempts failed, and Let's Encrypt allows only 5 identical certificates per week. We stop short so you are never locked out for a week.",
      fixes: [
        "Fix the cause named in the technical details below.",
        "Renewal resumes on its own at the time shown — no action needed after the fix.",
      ],
      retryHelps: false,
    };
  }
  if (/issuance is switched off|ENABLE_REAL_SSL|ENABLE_PAID_SSL/i.test(t)) {
    return {
      kind: "issuance-off",
      title: "Certificate issuance isn't switched on for this server yet",
      why: "Nothing was requested and nothing was installed, so this certificate is not active.",
      fixes: ["Open a support ticket and we will enable issuance, then request the certificate again."],
      retryHelps: false,
    };
  }
  if (/too many certificates|rateLimited|rate limit|already reached Let's Encrypt/i.test(t)) {
    return {
      kind: "rate-limit",
      title: "The weekly certificate limit for this domain is used up",
      why: "Let's Encrypt issues at most 5 identical certificates per domain per week.",
      fixes: ["Wait until the time in the details below, then try once more.", "Avoid deleting and re-requesting — every attempt counts."],
      retryHelps: false,
    };
  }
  if (/CAA record/i.test(t)) {
    return {
      kind: "caa",
      title: `A CAA record on ${domain} blocks Let's Encrypt`,
      why: "Your DNS says only certain certificate authorities may issue for this domain, and Let's Encrypt isn't one of them.",
      fixes: [
        'Add a CAA record: 0 issue "letsencrypt.org" — or remove the existing CAA record.',
        "Wait a few minutes for DNS to update, then try again.",
      ],
      retryHelps: true,
    };
  }
  if (/NXDOMAIN|DNS problem|no valid A records|SERVFAIL|does not resolve/i.test(t)) {
    return {
      kind: "dns",
      title: `${domain} doesn't point at your server yet`,
      why: "Let's Encrypt looked the domain up in DNS and found no usable address for it.",
      fixes: [
        "At your DNS host, add an A record for this exact name pointing to your server's IP address.",
        "Wait for DNS to update (usually minutes, sometimes up to an hour).",
        "Run the checks on the New certificate page before trying again.",
      ],
      retryHelps: true,
    };
  }
  if (/Could not bind|Address already in use|holds port 80/i.test(t)) {
    return {
      kind: "port80-busy",
      title: "Another program is using port 80 on your server",
      why: "Validation needs port 80 for a few seconds, and something else is holding it.",
      fixes: [
        "Stop whatever is listening on port 80 (sudo ss -ltnp 'sport = :80' shows it), or",
        "run nginx or Apache on port 80 — we use its plugin automatically when it is detected.",
      ],
      retryHelps: true,
    };
  }
  if (/Timeout during connect|likely firewall|Connection refused|connection.*timed out|Fetching http/i.test(t) && !/SSH/i.test(t)) {
    return {
      kind: "port80-blocked",
      title: "Let's Encrypt couldn't reach your server on port 80",
      why: "Validation is a plain web request to your domain on port 80. It timed out or was refused.",
      fixes: [
        "Open port 80 (TCP) in your server's firewall (for example: sudo ufw allow 80/tcp).",
        "Make sure the domain's A record points at this server and not at an old host.",
        "If the domain is behind a proxy such as Cloudflare, switch the record to DNS-only while issuing.",
      ],
      retryHelps: true,
    };
  }
  if (/unauthorized|Invalid response from|\b404\b/i.test(t)) {
    return {
      kind: "wrong-target",
      title: "Something other than your server answered for this domain",
      why: "Let's Encrypt reached a web server, but it wasn't the one holding the challenge — usually DNS still points at an old host or a proxy is answering first.",
      fixes: [
        "Check the domain's A record points at this server's IP.",
        "Remove any AAAA (IPv6) record that points somewhere else — Let's Encrypt tries IPv6 first.",
        "Turn off proxying (e.g. Cloudflare's orange cloud) while the certificate is issued.",
      ],
      retryHelps: true,
    };
  }
  if (/certbot install failed|No supported package manager|certbot still not available|plugin install failed/i.test(t)) {
    return {
      kind: "certbot-install",
      title: "We couldn't install the certificate tool on your server",
      why: "Issuance runs certbot on your server, and installing it failed. This happens before Let's Encrypt is contacted, so it did not use any of your weekly attempts.",
      fixes: [
        "Make sure the server can reach its package mirrors (sudo apt-get update should succeed).",
        "Free some disk space if the disk is full, then try again.",
      ],
      retryHelps: true,
    };
  }
  if (/SSH|connection details are pending|no root password|not reachable yet|Authentication failed|ECONNREFUSED|EHOSTUNREACH/i.test(t)) {
    return {
      kind: "server-unreachable",
      title: "We couldn't connect to your server",
      why: "Issuance logs in to your server to run certbot, and the connection failed. No attempt reached Let's Encrypt.",
      fixes: [
        "Check the server is running and you can still SSH in.",
        "If you changed the root password or disabled password login, reset access from the server's page.",
      ],
      retryHelps: true,
    };
  }
  if (/nothing is serving it for https/i.test(t)) {
    return {
      kind: "not-installed",
      title: "The certificate was issued, but your website isn't using it yet",
      why: "We obtained a valid certificate, but nothing on port 443 is serving it, so visitors don't get HTTPS.",
      fixes: [
        `Point your web server's TLS settings at /etc/letsencrypt/live/${domain}/fullchain.pem and privkey.pem.`,
        "Reload the web server (for example: sudo systemctl reload nginx).",
        "We re-check automatically about every 30 minutes; this notice clears when it is live.",
      ],
      retryHelps: false,
    };
  }
  if (/different hostname/i.test(t)) {
    return {
      kind: "wrong-name",
      title: "Your website is serving a certificate for a different name",
      why: "Visitors see a name-mismatch warning because port 443 presents another domain's certificate.",
      fixes: [`Configure the site for ${domain} to use this domain's certificate files, then reload the web server.`],
      retryHelps: false,
    };
  }
  if (/NOT trusted by browsers/i.test(t)) {
    return {
      kind: "untrusted",
      title: "Browsers don't trust the certificate being served",
      why: "The right name is served, but the chain is incomplete or self-signed.",
      fixes: ["Serve fullchain.pem (not cert.pem) as the certificate file, then reload the web server."],
      retryHelps: false,
    };
  }
  if (/NOT the certificate we issued/i.test(t)) {
    return {
      kind: "cdn",
      title: "Visitors are seeing a CDN's certificate, not this one",
      why: "The domain sits behind a proxy that terminates HTTPS at its edge. Your own certificate still matters — the proxy uses it to reach your server.",
      fixes: ["Nothing to do if this is intended. Keep auto-renew on so the origin certificate never lapses."],
      retryHelps: false,
    };
  }
  if (/Issuance stopped before it finished|Issuance ended without recording|No issuance job ever ran/i.test(t)) {
    return {
      kind: "stalled",
      title: "The request stopped before it finished",
      why: "The job was interrupted, so we can't confirm a certificate exists. Nothing is being reported as active.",
      fixes: ["Delete this record and request the certificate again."],
      retryHelps: true,
    };
  }
  if (/expired on/i.test(t)) {
    return {
      kind: "served-expired",
      title: "The certificate your site serves has expired",
      why: "Visitors see a browser security warning until a new one is installed.",
      fixes: ["Renew now, then reload your web server so it picks up the new files."],
      retryHelps: true,
    };
  }
  if (/expiry could not be read back|real expiry could not be read/i.test(t)) {
    return {
      kind: "expiry-unreadable",
      title: "We couldn't confirm the certificate's expiry date",
      why: "certbot reported success, but the date couldn't be read back, so we don't report it as active.",
      fixes: ["Requesting again is safe."],
      retryHelps: true,
    };
  }
  if (/not yet due for renewal|reused it rather than requesting/i.test(t)) {
    return {
      kind: "unchanged",
      title: "Nothing needed renewing",
      why: "certbot kept the existing certificate because it isn't due yet.",
      fixes: ["No action needed."],
      retryHelps: false,
    };
  }
  return {
    kind: "unknown",
    title: "The last attempt didn't succeed",
    why: "The technical details below are the exact message we received.",
    fixes: ["Run the checks on the New certificate page, fix anything flagged, then try again.", "If it keeps failing, open a support ticket and include the details."],
    retryHelps: true,
  };
}

// ---------------------------------------------------------------------------
// Live readiness checks (the issue flow)
// ---------------------------------------------------------------------------

export type CheckState = "pass" | "warn" | "fail" | "skip";

export type ReadinessCheck = {
  id: "name" | "dns" | "target" | "ipv6" | "port80" | "limit" | "server";
  label: string;
  state: CheckState;
  detail: string;
  fix?: string;
};

export type ReadinessFacts = {
  domain: string;
  domainValid: boolean;
  /** The public address the chosen server answers on, or null if unknown. */
  serverAddress: string | null;
  /** True when that address is shared (no dedicated IP on the server). */
  sharedAddress: boolean;
  /** Public A records, or null when the lookup itself errored. */
  a: string[] | null;
  aaaa: string[];
  dnsError: string | null;
  /** HTTP request to the domain on port 80. null = not attempted. */
  http: { reached: boolean; status?: number; error?: string } | null;
  attempts: { total: number; leRelevant: number; resumesAt: string | null };
  maxLeAttempts: number;
  maxTotalAttempts: number;
  serverBusy: boolean;
  existing: "active" | "inflight" | null;
};

export type Readiness = {
  checks: ReadinessCheck[];
  /** A check failed that will certainly make issuance fail. */
  blocked: boolean;
  /** Something looks wrong but issuance might still work. */
  warnings: number;
  /** Request is refused server-side regardless (rate limit, duplicate, busy). */
  hardStop: string | null;
};

/** Turn observed facts into the checklist the issue flow shows. Pure. */
export function readinessVerdict(f: ReadinessFacts): Readiness {
  const checks: ReadinessCheck[] = [];

  checks.push(
    f.domainValid
      ? { id: "name", label: "Domain name", state: "pass", detail: `${f.domain} is a valid hostname.` }
      : {
          id: "name", label: "Domain name", state: "fail",
          detail: "That isn't a hostname we can issue for.",
          fix: "Use a bare name like app.example.com — no https://, port, path or wildcard (*).",
        }
  );

  if (!f.domainValid) {
    for (const [id, label] of [["dns", "DNS record"], ["target", "Points at your server"], ["port80", "Port 80 reachable"]] as const) {
      checks.push({ id, label, state: "skip", detail: "Waiting for a valid domain name." });
    }
  } else {
    const a = f.a ?? [];
    if (f.a === null || a.length === 0) {
      checks.push({
        id: "dns", label: "DNS record", state: "fail",
        detail: f.dnsError ? `No A record found (${f.dnsError}).` : `No A record found for ${f.domain}.`,
        fix: f.serverAddress
          ? `Add an A record for ${f.domain} → ${f.serverAddress} at your DNS host.`
          : `Add an A record for ${f.domain} pointing to your server's IP address.`,
      });
      checks.push({ id: "target", label: "Points at your server", state: "skip", detail: "Needs a DNS record first." });
    } else {
      checks.push({ id: "dns", label: "DNS record", state: "pass", detail: `Resolves to ${a.join(", ")}.` });
      if (!f.serverAddress) {
        checks.push({
          id: "target", label: "Points at your server", state: "warn",
          detail: "This server's public address isn't known yet, so we can't compare.",
        });
      } else if (!a.includes(f.serverAddress)) {
        checks.push({
          id: "target", label: "Points at your server", state: "fail",
          detail: `${f.domain} points to ${a.join(", ")}, but this server is ${f.serverAddress}.`,
          fix: `Change the A record to ${f.serverAddress}, wait a few minutes, then check again.`,
        });
      } else if (a.length > 1) {
        checks.push({
          id: "target", label: "Points at your server", state: "warn",
          detail: `One of ${a.length} addresses is this server. Let's Encrypt may validate against any of them.`,
          fix: `Remove the other A records so ${f.domain} resolves only to ${f.serverAddress}.`,
        });
      } else if (f.sharedAddress) {
        checks.push({
          id: "target", label: "Points at your server", state: "warn",
          detail: `${f.serverAddress} is a shared address, so port 80 on it may not reach your server.`,
          fix: "Add a dedicated IP to this server for reliable validation, then point the domain at it.",
        });
      } else {
        checks.push({ id: "target", label: "Points at your server", state: "pass", detail: `Matches this server (${f.serverAddress}).` });
      }
    }

    if (f.aaaa.length > 0) {
      checks.push({
        id: "ipv6", label: "IPv6 (AAAA) record", state: "warn",
        detail: `${f.domain} also has an IPv6 address (${f.aaaa.join(", ")}). Let's Encrypt tries IPv6 first.`,
        fix: "If that address isn't this server, remove the AAAA record before requesting.",
      });
    }

    if (f.http === null) {
      checks.push({ id: "port80", label: "Port 80 reachable", state: "skip", detail: "Needs a DNS record first." });
    } else if (f.http.reached) {
      checks.push({
        id: "port80", label: "Port 80 reachable", state: "pass",
        detail: `A web request to http://${f.domain} got an answer${f.http.status ? ` (HTTP ${f.http.status})` : ""}.`,
      });
    } else {
      checks.push({
        id: "port80", label: "Port 80 reachable", state: "fail",
        detail: `A web request to http://${f.domain} failed${f.http.error ? ` — ${f.http.error}` : ""}.`,
        fix: "Open TCP port 80 in the server's firewall (e.g. sudo ufw allow 80/tcp) and check the A record.",
      });
    }
  }

  // Rate limit + platform invariants: these mirror the refusals in lib/actions-ssl.ts.
  let hardStop: string | null = null;
  const used = f.attempts.leRelevant;
  const left = Math.max(0, f.maxLeAttempts - used);
  const limitHit = used >= f.maxLeAttempts || f.attempts.total >= f.maxTotalAttempts;
  const resumes = f.attempts.resumesAt ? ` after ${f.attempts.resumesAt.slice(0, 16).replace("T", " ")} UTC` : " later this week";
  if (limitHit) {
    hardStop = `The weekly attempt limit for ${f.domain} is used up. You can try again${resumes}.`;
    checks.push({ id: "limit", label: "Weekly attempts", state: "fail", detail: hardStop });
  } else if (f.domainValid) {
    checks.push({
      id: "limit", label: "Weekly attempts", state: used >= 2 ? "warn" : "pass",
      detail: `${left} of ${f.maxLeAttempts} attempts left this week for ${f.domain}.`,
      ...(used >= 2 ? { fix: "Fix anything flagged above before requesting — each failed attempt counts." } : {}),
    });
  }

  if (f.existing === "active") {
    hardStop = hardStop ?? `You already have an active certificate for ${f.domain}.`;
    checks.push({ id: "server", label: "Server ready", state: "fail", detail: `You already have an active certificate for ${f.domain}.` });
  } else if (f.existing === "inflight") {
    hardStop = hardStop ?? `A certificate for ${f.domain} is already being issued.`;
    checks.push({ id: "server", label: "Server ready", state: "fail", detail: `A certificate for ${f.domain} is already being issued.` });
  } else if (f.serverBusy) {
    hardStop = hardStop ?? "Another operation is running on this server. Try again when it finishes.";
    checks.push({
      id: "server", label: "Server ready", state: "fail",
      detail: "Another operation is queued or running on this server — certificates wait for it to finish.",
    });
  } else {
    checks.push({ id: "server", label: "Server ready", state: "pass", detail: "No other work is queued on this server." });
  }

  const blocked = checks.some((c) => c.state === "fail");
  const warnings = checks.filter((c) => c.state === "warn").length;
  return { checks, blocked, warnings, hardStop };
}

