/* Shared vector-art primitives for the customer portal.
 *
 * WHY THIS FILE EXISTS. Several portal pages (SSL first; Support and Domains are
 * being overhauled in parallel) carried raster hero renders — e.g. the old
 * 900x600 `hero-ssl-shield.webp`, drawn at ~450px wide so it was at best 1x on
 * a retina screen, with its glow and palette baked into pixels that could not
 * follow light mode. Everything here is inline SVG that reads its colours from
 * the theme tokens (`--color-blue`, `--color-violet`, `--color-magenta`,
 * `--color-cyan`, `--color-surface`, `--color-rim-hi`…), so it is crisp at any
 * density and flips with the theme for free.
 *
 * Every <defs> id is namespaced by the caller's `uid`, because two SVGs on one
 * page that both define `id="grad"` silently share whichever was parsed first.
 *
 * Decorative only: callers wrap these in an `aria-hidden` container.
 */

export type VectorTone = "blue" | "violet" | "magenta" | "cyan" | "mint" | "amber" | "rose";

/** The CSS variable for a tone. */
export const toneVar = (t: VectorTone) => `var(--color-${t})`;

/** Brand ramp (blue → violet → magenta) + a soft halo, namespaced by `uid`. */
export function BrandDefs({ uid }: { uid: string }) {
  return (
    <defs>
      <linearGradient id={`${uid}-brand`} x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" style={{ stopColor: "var(--color-blue)" }} />
        <stop offset="55%" style={{ stopColor: "var(--color-violet)" }} />
        <stop offset="100%" style={{ stopColor: "var(--color-magenta)" }} />
      </linearGradient>
      <linearGradient id={`${uid}-brand-h`} x1="0" y1="0" x2="1" y2="0">
        <stop offset="0%" style={{ stopColor: "var(--color-cyan)", stopOpacity: 0 }} />
        <stop offset="30%" style={{ stopColor: "var(--color-blue)" }} />
        <stop offset="70%" style={{ stopColor: "var(--color-violet)" }} />
        <stop offset="100%" style={{ stopColor: "var(--color-magenta)", stopOpacity: 0 }} />
      </linearGradient>
      <linearGradient id={`${uid}-panel`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" style={{ stopColor: "var(--color-surface)" }} />
        <stop offset="100%" style={{ stopColor: "var(--color-well)" }} />
      </linearGradient>
      <radialGradient id={`${uid}-halo`} cx="50%" cy="50%" r="50%">
        <stop offset="0%" style={{ stopColor: "var(--color-blue)", stopOpacity: 0.34 }} />
        <stop offset="55%" style={{ stopColor: "var(--color-violet)", stopOpacity: 0.12 }} />
        <stop offset="100%" style={{ stopColor: "var(--color-violet)", stopOpacity: 0 }} />
      </radialGradient>
      <pattern id={`${uid}-dots`} width="16" height="16" patternUnits="userSpaceOnUse">
        <circle cx="1.5" cy="1.5" r="1" style={{ fill: "var(--color-tx-faint)" }} opacity="0.32" />
      </pattern>
      <radialGradient id={`${uid}-fade`} cx="50%" cy="50%" r="50%">
        <stop offset="0%" stopColor="#fff" stopOpacity="1" />
        <stop offset="100%" stopColor="#fff" stopOpacity="0" />
      </radialGradient>
      <mask id={`${uid}-dotmask`}>
        <rect width="100%" height="100%" fill={`url(#${uid}-fade)`} />
      </mask>
    </defs>
  );
}

/** A faded dot field + halo, the shared backdrop for hero compositions. */
export function HaloField({ uid, w, h }: { uid: string; w: number; h: number }) {
  return (
    <g>
      <ellipse cx={w / 2} cy={h / 2} rx={w * 0.5} ry={h * 0.5} fill={`url(#${uid}-halo)`} />
      <rect width={w} height={h} fill={`url(#${uid}-dots)`} mask={`url(#${uid}-dotmask)`} />
    </g>
  );
}

/**
 * Two tilted orbit ellipses with a travelling "live" node. The node is the one
 * rationed neon element (cyan = live), and it holds still under reduced motion
 * (`.nx-va-orbit` is paused by the global reduced-motion rule's fill-forwards).
 */
export function Orbit({
  uid, cx, cy, rx, ry, tilt = -14, live = true,
}: {
  uid: string; cx: number; cy: number; rx: number; ry: number; tilt?: number; live?: boolean;
}) {
  const path = `M ${cx - rx} ${cy} a ${rx} ${ry} 0 1 0 ${rx * 2} 0 a ${rx} ${ry} 0 1 0 ${-rx * 2} 0`;
  return (
    <g transform={`rotate(${tilt} ${cx} ${cy})`}>
      <ellipse cx={cx} cy={cy} rx={rx} ry={ry} fill="none" stroke={`url(#${uid}-brand-h)`} strokeWidth="1.6" />
      <ellipse cx={cx} cy={cy} rx={rx * 0.82} ry={ry * 0.74} fill="none"
               style={{ stroke: "var(--color-rim-hi)" }} strokeWidth="1" strokeDasharray="2 6" />
      {live && (
        <g>
          <circle r="7" style={{ fill: "var(--color-cyan)" }} opacity="0.18">
            <animateMotion dur="14s" repeatCount="indefinite" path={path} />
          </circle>
          <circle r="3" style={{ fill: "var(--color-cyan)" }}>
            <animateMotion dur="14s" repeatCount="indefinite" path={path} />
          </circle>
        </g>
      )}
    </g>
  );
}

/** A padlock glyph built from primitives. (x, y) = top-left of the body. */
export function Padlock({
  uid, x, y, w = 64, closed = true,
}: { uid: string; x: number; y: number; w?: number; closed?: boolean }) {
  const h = w * 0.8;
  const sw = w * 0.15;
  const r = w * 0.32;
  const sx = x + w / 2;
  const lift = closed ? 0 : w * 0.18;
  return (
    <g>
      <path
        d={`M ${sx - r} ${y + 2 - lift} V ${y - r * 0.55 - lift} a ${r} ${r} 0 0 1 ${r * 2} 0 V ${y + (closed ? 2 : -r * 0.4) - lift}`}
        fill="none" stroke={`url(#${uid}-brand)`} strokeWidth={sw} strokeLinecap="round"
      />
      <rect x={x} y={y} width={w} height={h} rx={w * 0.18} fill={`url(#${uid}-brand)`} />
      <rect x={x + 1.5} y={y + 1.5} width={w - 3} height={h * 0.42} rx={w * 0.16} fill="#fff" opacity="0.12" />
      <circle cx={sx} cy={y + h * 0.44} r={w * 0.09} fill="#fff" opacity="0.92" />
      <rect x={sx - w * 0.035} y={y + h * 0.48} width={w * 0.07} height={h * 0.24} rx={w * 0.035} fill="#fff" opacity="0.92" />
    </g>
  );
}

/** A rounded "document" panel with placeholder text lines. */
export function DocPanel({
  uid, x, y, w, h, lines = 3,
}: { uid: string; x: number; y: number; w: number; h: number; lines?: number }) {
  return (
    <g>
      <rect x={x} y={y} width={w} height={h} rx="14" fill={`url(#${uid}-panel)`}
            style={{ stroke: "var(--color-rim-hi)" }} strokeWidth="1.2" />
      <rect x={x} y={y} width={w} height="4" rx="2" fill={`url(#${uid}-brand)`} opacity="0.9" />
      {Array.from({ length: lines }).map((_, i) => (
        <rect key={i} x={x + 18} y={y + 26 + i * 16} width={(w - 36) * (i === 0 ? 0.62 : i % 2 ? 0.84 : 0.5)}
              height={i === 0 ? 8 : 6} rx="3"
              style={{ fill: i === 0 ? "var(--color-tx-mute)" : "var(--color-rim-hi)" }}
              opacity={i === 0 ? 0.55 : 0.9} />
      ))}
    </g>
  );
}

