import { Icon } from "@/components/nx/Icon";
import { BrandDefs, DocPanel, HaloField, Orbit, Padlock, toneVar, type VectorTone } from "@/components/nx/visual/VectorArt";
import type { CertState, CertView } from "@/lib/ssl-status";

/* Vector art for the SSL pages. Replaces the raster `hero-ssl-shield.webp`
 * (900x600 AI render, soft at 2x, palette baked in, hidden on phones leaving an
 * empty 280px band) with compositions built from VectorArt primitives. */

/** Hero: a certificate panel, its trust chain, a padlock and the live orbit. */
export function CertificateHeroArt({ uid = "sslhero" }: { uid?: string }) {
  const W = 400, H = 224;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="h-full w-full" preserveAspectRatio="xMidYMid meet" role="presentation">
      <BrandDefs uid={uid} />
      <HaloField uid={uid} w={W} h={H} />
      <Orbit uid={uid} cx={210} cy={118} rx={176} ry={58} tilt={-10} />

      {/* Trust chain: root → intermediate → this certificate. */}
      <g opacity="0.95">
        <path d="M 330 34 V 66 M 330 92 V 124" style={{ stroke: "var(--color-rim-hi)" }} strokeWidth="1.5" strokeDasharray="3 4" />
        {[{ y: 22, t: "violet" }, { y: 80, t: "blue" }, { y: 138, t: "cyan" }].map((n) => (
          <g key={n.y}>
            <rect x={312} y={n.y} width="36" height="24" rx="7" fill={`url(#${uid}-panel)`}
                  style={{ stroke: toneVar(n.t as VectorTone) }} strokeWidth="1.3" />
            <rect x={320} y={n.y + 9} width="20" height="5" rx="2.5" style={{ fill: toneVar(n.t as VectorTone) }} opacity="0.75" />
          </g>
        ))}
      </g>

      <DocPanel uid={uid} x={92} y={56} w={196} h={128} lines={4} />
      {/* Seal + ribbon, bottom-right of the certificate. */}
      <g transform="translate(252 160)">
        <path d="M -9 6 L -14 30 L -4 24 L 2 32 L 6 8 Z" fill={`url(#${uid}-brand)`} opacity="0.85" />
        <circle r="20" fill={`url(#${uid}-brand)`} />
        <circle r="15" fill="none" stroke="#fff" strokeOpacity="0.45" strokeWidth="1.2" strokeDasharray="2 2.6" />
        <path d="M -7 0 L -2 5 L 8 -5" fill="none" stroke="#fff" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
      </g>
      <Padlock uid={uid} x={62} y={104} w={58} />
    </svg>
  );
}

/** Empty state: an open padlock beside a blank certificate, waiting to be issued. */
export function EmptyCertArt({ uid = "sslempty" }: { uid?: string }) {
  const W = 260, H = 170;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="h-full w-full" role="presentation">
      <BrandDefs uid={uid} />
      <HaloField uid={uid} w={W} h={H} />
      <Orbit uid={uid} cx={130} cy={92} rx={118} ry={40} tilt={-8} />
      <g opacity="0.95">
        <rect x={78} y={44} width="128" height="88" rx="12" fill={`url(#${uid}-panel)`}
              style={{ stroke: "var(--color-rim-hi)" }} strokeWidth="1.2" strokeDasharray="5 4" />
        <rect x={96} y={66} width="70" height="7" rx="3.5" style={{ fill: "var(--color-rim-hi)" }} />
        <rect x={96} y={81} width="92" height="5" rx="2.5" style={{ fill: "var(--color-rim-hi)" }} opacity="0.7" />
        <rect x={96} y={93} width="56" height="5" rx="2.5" style={{ fill: "var(--color-rim-hi)" }} opacity="0.7" />
        <circle cx={182} cy={114} r="11" fill="none" style={{ stroke: "var(--color-rim-hi)" }} strokeWidth="1.4" strokeDasharray="3 3" />
      </g>
      <Padlock uid={uid} x={50} y={86} w={46} closed={false} />
    </svg>
  );
}

const TONE_VAR: Record<CertView["tone"], string> = {
  mint: "var(--color-mint)", amber: "var(--color-amber)", rose: "var(--color-rose)",
  blue: "var(--color-blue)", violet: "var(--color-violet)",
};

/**
 * The expiry gauge. The arc is the remaining share of the certificate's REAL
 * lifetime (observed issue → observed expiry). With either date missing there is
 * no arc at all — the ring never draws a computed 90-day guess.
 */
export function ExpiryRing({
  view, size = 132, uid = "ring",
}: { view: Pick<CertView, "daysLeft" | "lifeLeft" | "tone" | "state">; size?: number; uid?: string }) {
  const r = 52, c = 2 * Math.PI * r;
  const frac = view.lifeLeft;
  const big = view.daysLeft === null ? "—" : String(Math.abs(view.daysLeft));
  const unit =
    view.daysLeft === null ? (view.state === "pending" || view.state === "issuing" ? "issuing" : "no expiry yet")
    : view.daysLeft < 0 ? (Math.abs(view.daysLeft) === 1 ? "day ago" : "days ago")
    : view.daysLeft === 1 ? "day left" : "days left";
  return (
    <div className="relative grid flex-none place-items-center" style={{ width: size, height: size }}>
      <svg viewBox="0 0 132 132" width={size} height={size} aria-hidden className="-rotate-90">
        <defs>
          <linearGradient id={`${uid}-g`} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" style={{ stopColor: TONE_VAR[view.tone] }} />
            <stop offset="100%" style={{ stopColor: view.tone === "mint" ? "var(--color-cyan)" : TONE_VAR[view.tone] }} />
          </linearGradient>
        </defs>
        <circle cx="66" cy="66" r={r} fill="none" style={{ stroke: "var(--color-rim)" }} strokeWidth="9" />
        {frac !== null && frac > 0 && (
          <circle cx="66" cy="66" r={r} fill="none" stroke={`url(#${uid}-g)`} strokeWidth="9" strokeLinecap="round"
                  strokeDasharray={`${c * frac} ${c}`} />
        )}
      </svg>
      <span className="absolute inset-0 flex flex-col items-center justify-center text-center">
        <span suppressHydrationWarning className="num text-[30px] font-extrabold leading-none text-white">{big}</span>
        <span className="mt-1 text-[11.5px] font-semibold text-tx-dim">{unit}</span>
      </span>
    </div>
  );
}

const GLYPH: Record<CertState, { icon: string; tone: CertView["tone"] }> = {
  active: { icon: "shieldcheck", tone: "mint" },
  expiring: { icon: "clock", tone: "amber" },
  attention: { icon: "warntriangle", tone: "amber" },
  unverified: { icon: "warncircle", tone: "amber" },
  expired: { icon: "unlock", tone: "rose" },
  failed: { icon: "xcircle", tone: "rose" },
  pending: { icon: "clock2", tone: "blue" },
  issuing: { icon: "refresh", tone: "blue" },
};

/** The tinted status tile that leads every certificate row. */
export function StateGlyph({ state, size = 44 }: { state: CertState; size?: number }) {
  const g = GLYPH[state];
  const col = TONE_VAR[g.tone];
  return (
    <span
      className="relative grid flex-none place-items-center rounded-[13px] border"
      style={{
        width: size, height: size, color: col,
        borderColor: `color-mix(in srgb, ${col} 38%, transparent)`,
        background: `linear-gradient(180deg, color-mix(in srgb, ${col} 16%, transparent), color-mix(in srgb, ${col} 5%, transparent))`,
      }}
    >
      <Icon name={g.icon} size={size * 0.4} tone="inherit" className={state === "issuing" ? "motion-safe:animate-spin [animation-duration:2.4s]" : ""} />
    </span>
  );
}

/** Tone chip with a dot. */
export function StatusChip({ view }: { view: Pick<CertView, "label" | "tone"> }) {
  const col = TONE_VAR[view.tone];
  return (
    <span
      className="inline-flex items-center gap-1.5 whitespace-nowrap rounded-full border px-2.5 py-[3px] text-[12px] font-bold"
      style={{ color: col, borderColor: `color-mix(in srgb, ${col} 40%, transparent)`, background: `color-mix(in srgb, ${col} 10%, transparent)` }}
    >
      <span className="h-1.5 w-1.5 rounded-full" style={{ background: col }} />
      {view.label}
    </span>
  );
}

/**
 * How HTTP validation works, in three hops. A responsive HTML composition
 * rather than one SVG, so it can stack on a phone without shrinking its text.
 */
export function ValidationFlow({ domain = "your domain", address }: { domain?: string; address?: string | null }) {
  const steps = [
    { icon: "certbadge", tone: "violet", title: "Let's Encrypt asks", body: `"Prove you control ${domain}."` },
    { icon: "globe", tone: "blue", title: "DNS answers", body: address ? `${domain} → ${address}` : `${domain} → your server's IP` },
    { icon: "server", tone: "cyan", title: "Your server replies", body: "on port 80, for a few seconds" },
  ];
  return (
    <ol className="relative grid gap-3 sm:grid-cols-3 sm:gap-2">
      {steps.map((s, i) => (
        <li key={s.title} className="relative flex items-start gap-3 sm:flex-col sm:items-center sm:text-center">
          {i < steps.length - 1 && (
            <span aria-hidden className="absolute left-[21px] top-[46px] h-[calc(100%-34px)] w-px sm:left-[calc(50%+30px)] sm:top-[22px] sm:h-px sm:w-[calc(100%-60px)]"
                  style={{ background: "linear-gradient(90deg, var(--color-blue), var(--color-violet))", opacity: 0.55 }} />
          )}
