p='lib/actions-ssl.ts'
s=open(p).read()
s=s.replace('''import type { SslCertificate } from "@prisma/client";''','''import type { SslCertificate } from "@prisma/client";
import { Resolver } from "node:dns/promises";
import { request as httpRequest } from "node:http";
import { checkRateLimit } from "./rate-limit";
