import { readinessVerdict, type Readiness } from "./ssl-status";''')
s+='''
// ---------------------------------------------------------------------------
// Live readiness checks for the issue flow (read-only)
// ---------------------------------------------------------------------------

const CHECK_TIMEOUT_MS = 5_000;

/** The public address a server answers on — the same resolution connectionTarget() uses. */
function serverAddressOf(server: { dedicatedIp: { address: string } | null; node: { publicIp: string } | null }) {
  const dedicated = server.dedicatedIp?.address ?? null;
  const address = dedicated ?? server.node?.publicIp ?? process.env.PUBLIC_IP ?? null;
  return { address: address || null, shared: !dedicated };
}

function withTimeout<T>(p: Promise<T>): Promise<T> {
  return Promise.race([
    p,
    new Promise<T>((_, rej) => setTimeout(() => rej(new Error("timed out")), CHECK_TIMEOUT_MS)),
  ]);
}

function dnsCode(e: unknown): string {
  const code = (e as { code?: string })?.code;
  if (code === "ENOTFOUND" || code === "ENODATA") return "no record";
  if (code === "ESERVFAIL") return "the DNS server failed";
  if (code === "ETIMEOUT" || /timed out/.test(String((e as Error)?.message))) return "lookup timed out";
  return code ? code.toLowerCase() : "lookup failed";
}

/**
 * One plain HTTP request to the domain on port 80, sent to a VETTED public IP
 * with the real Host header (so DNS cannot rebind between check and connect).
 * Any HTTP answer at all — a 404 included — proves port 80 is reachable, which is
 * all HTTP-01 needs. No redirects are followed, nothing is written anywhere.
 */
function probePort80(ip: string, domain: string): Promise<{ reached: boolean; status?: number; error?: string }> {
  return new Promise((resolve) => {
    let settled = false;
    const done = (r: { reached: boolean; status?: number; error?: string }) => {
      if (!settled) { settled = true; resolve(r); }
    };
    const req = httpRequest(
      {
        host: ip, port: 80, method: "GET", path: "/.well-known/acme-challenge/nxeon-readiness-check",
        headers: { Host: domain, "User-Agent": "Nxeon-SSL-Readiness/1.0" }, timeout: CHECK_TIMEOUT_MS,
      },
      (res) => { res.resume(); done({ reached: true, status: res.statusCode }); req.destroy(); }
    );
    req.on("timeout", () => { req.destroy(); done({ reached: false, error: "no answer within 5 seconds (port 80 may be firewalled)" }); });
    req.on("error", (e: NodeJS.ErrnoException) =>
      done({
        reached: false,
        error: e.code === "ECONNREFUSED" ? "connection refused — nothing is listening on port 80"
          : e.code === "EHOSTUNREACH" || e.code === "ENETUNREACH" ? "the address is unreachable"
          : "the request failed",
      })
    );
    req.end();
  });
}

/**
 * Pre-flight checks for a certificate request, run live from the issue flow.
 *
 * READ-ONLY: it resolves DNS, makes one HTTP request to the domain, and reads the
 * same counters `requestCertificate` enforces. It never creates a job, never
 * contacts Let's Encrypt and never touches the server — so it costs none of the
 * customer's weekly attempts. Rate-limited per user because each call does real
 * network I/O on their behalf.
 */
export async function checkSslReadiness(serverId: string, domain: string): Promise<{ error?: string; readiness?: Readiness; address?: string | null; shared?: boolean }> {
  let user;
  try {
    user = await requireUser();
  } catch (e: any) {
    return { error: e.message };
  }
  const rl = checkRateLimit(`ssl:readiness:${user.id}`, { max: 12, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many checks — try again in ${rl.retryAfterSec}s.` };

  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, userId: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) return { error: "Server not found." };

  const clean = String(domain ?? "").toLowerCase().trim().replace(/\\.$/, "");
  const domainValid = FQDN_RE.test(clean);
  const { address, shared } = serverAddressOf(server);

  let a: string[] | null = null;
  let aaaa: string[] = [];
  let dnsError: string | null = null;
  let http: { reached: boolean; status?: number; error?: string } | null = null;

  if (domainValid) {
    const resolver = new Resolver({ timeout: CHECK_TIMEOUT_MS, tries: 2 });
    const [r4, r6] = await Promise.allSettled([withTimeout(resolver.resolve4(clean)), withTimeout(resolver.resolve6(clean))]);
    if (r4.status === "fulfilled") a = r4.value;
    else dnsError = dnsCode(r4.reason);
