 * with the real Host header (so DNS cannot rebind between check and connect).
 * Any HTTP answer at all — a 404 included — proves port 80 is reachable, which is
 * all HTTP-01 needs. No redirects are followed, nothing is written anywhere.
 */
function probePort80(ip: string, domain: string): Promise<{ reached: boolean; status?: number; error?: string }> {
  return new Promise((resolve) => {
    let settled = false;
    const done = (r: { reached: boolean; status?: number; error?: string }) => {
      if (!settled) { settled = true; resolve(r); }
    };
    const req = httpRequest(
      {
        host: ip, port: 80, method: "GET", path: "/.well-known/acme-challenge/nxeon-readiness-check",
        headers: { Host: domain, "User-Agent": "Nxeon-SSL-Readiness/1.0" }, timeout: CHECK_TIMEOUT_MS,
      },
      (res) => { res.resume(); done({ reached: true, status: res.statusCode }); req.destroy(); }
    );
    req.on("timeout", () => { req.destroy(); done({ reached: false, error: "no answer within 5 seconds (port 80 may be firewalled)" }); });
    req.on("error", (e: NodeJS.ErrnoException) =>
      done({
        reached: false,
        error: e.code === "ECONNREFUSED" ? "connection refused — nothing is listening on port 80"
          : e.code === "EHOSTUNREACH" || e.code === "ENETUNREACH" ? "the address is unreachable"
          : "the request failed",
      })
    );
    req.end();
  });
}

