    domainValid
      ? db.sslCertificate.findFirst({
          where: { userId: user.id, domain: clean, status: { in: ["PENDING", "ISSUING", "ACTIVE"] } },
          select: { status: true },
        })
      : Promise.resolve(null),
    domainValid ? issueAttemptsFor(clean) : Promise.resolve({ total: 0, leRelevant: 0, resumesAt: null }),
    db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } }),
