    domain: clean || String(domain ?? ""),
    domainValid,
    serverAddress: address,
    sharedAddress: shared,
    a, aaaa, dnsError, http,
    attempts: { total: rate.total, leRelevant: rate.leRelevant, resumesAt: rate.resumesAt ? rate.resumesAt.toISOString() : null },
    maxLeAttempts: MAX_LE_ATTEMPTS_PER_WINDOW,
