"use client";

import Link from "next/link";
import { useMemo, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { toggleAutoRenew } from "@/lib/actions-ssl";
import { certView, explainSslError, type CertGroup } from "@/lib/ssl-status";
import type { QueueInfo } from "@/lib/ssl-queue";
import { EmptyCertArt, StateGlyph, StatusChip } from "./SslArt";
import { QueueNote } from "./QueueNote";

/**
 * The certificate list for /dashboard/ssl.
 *
 * Replaces the old five-column table (components/customer/SslCertificates.tsx),
 * which scrolled sideways on a phone, printed raw certbot output inline as the
 * row's subtitle, and put Renew/Delete beside every row. Each certificate is now
 * one object card — status tile, domain, the server it lives on, an observed
 * expiry countdown, auto-renew — with the plain-language reason for anything
 * wrong and a link into the certificate's own page, where the destructive
 * actions, renewal history and fixes live.
 *
 * Every state comes from lib/ssl-status.ts `certView`, which only uses observed
 * values: an ACTIVE row with no read-back expiry is "Unverified", never green.
 */

export type CertRow = {
  id: string;
  domain: string;
  status: string;
  issuer: string;
  autoRenew: boolean;
  serverId: string | null;
  serverName: string | null;
  issuedAt: string | null;
  /** The observed notAfter. Never a computed guess — null means "not verified". */
  expiresAt: string | null;
  lastError: string | null;
  queue: QueueInfo | null;
};

const ISSUER: Record<string, string> = { letsencrypt: "Let's Encrypt", rapidssl: "RapidSSL", sectigo: "Sectigo" };
export const issuerName = (i: string) => ISSUER[i] ?? i;

function fmtDate(iso: string) {
  return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });
}

type Filter = "all" | CertGroup;

function StatTile({
  icon, label, value, tone, on, onClick, foot,
}: {
  icon: string; label: string; value: number; tone: string; on: boolean; onClick: () => void; foot: string;
}) {
  const col = `var(--color-${tone})`;
  return (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={on}
      className={
        "group flex min-w-0 items-start gap-3 rounded-[15px] border px-4 py-3.5 text-left transition-colors " +
        (on ? "bg-[color-mix(in_srgb,var(--color-blue)_10%,var(--color-surface))]" : "bg-surface hover:bg-well")
      }
      style={{ borderColor: on ? `color-mix(in srgb, ${col} 55%, transparent)` : "var(--color-rim-hi)" }}
    >
      <span className="grid h-10 w-10 flex-none place-items-center rounded-[12px] border"
            style={{ color: col, borderColor: `color-mix(in srgb, ${col} 34%, transparent)`, background: `color-mix(in srgb, ${col} 11%, transparent)` }}>
        <Icon name={icon} size={16} tone="inherit" />
      </span>
      <span className="flex min-w-0 flex-col">
        <span className="num text-[24px] font-extrabold leading-none text-white">{value}</span>
        <span className="mt-1 text-[12.5px] font-semibold text-tx-body">{label}</span>
        <span className="mt-0.5 truncate text-[11.5px] text-tx-faint">{foot}</span>
      </span>
    </button>
  );
}

function AutoRenewSwitch({ cert }: { cert: CertRow }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <span className="flex flex-col items-start gap-1">
      <span className="flex items-center gap-2.5">
        <button
          type="button"
          role="switch"
          aria-checked={cert.autoRenew}
          aria-label={`Auto-renew for ${cert.domain}`}
          disabled={pending}
          onClick={() => start(async () => {
            setError(null);
            const r = await toggleAutoRenew(cert.id);
            if (r?.error) setError(r.error);
          })}
