                </Link>
              ) : (
                <>
                  <Link href="/dashboard/deploy" className="btn-primary inline-flex items-center gap-2">
                    <Icon name="server" size={13} tone="inherit" /> Deploy a server
                  </Link>
                  <span className="text-[12.5px] text-tx-faint">
                    A certificate is issued on a running server, so you&apos;ll need one first.
                  </span>
                </>
              )}
            </div>
          </div>
          <div aria-hidden className="mx-auto h-[170px] w-full max-w-[300px]">
            <EmptyCertArt />
          </div>
        </div>
      </section>
    );
  }

  return (
    <div className="flex flex-col gap-4">
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatTile icon="shieldcheck" tone="mint" label="Active" value={count("healthy")} foot="Valid and served" on={filter === "healthy"} onClick={() => setFilter(filter === "healthy" ? "all" : "healthy")} />
        <StatTile icon="clock" tone="amber" label="Renewing soon" value={count("expiring")} foot="21 days or less left" on={filter === "expiring"} onClick={() => setFilter(filter === "expiring" ? "all" : "expiring")} />
        <StatTile icon="warntriangle" tone="rose" label="Needs attention" value={count("attention")} foot="Failed, expired or not served" on={filter === "attention"} onClick={() => setFilter(filter === "attention" ? "all" : "attention")} />
        <StatTile icon="refresh" tone="blue" label="In progress" value={count("progress")} foot={waiting ? `${waiting} waiting in the queue` : "Queued or issuing"} on={filter === "progress"} onClick={() => setFilter(filter === "progress" ? "all" : "progress")} />
      </div>

      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-[12.5px] text-tx-dim" aria-live="polite">
          {filter === "all" ? `${certificates.length} certificate${certificates.length === 1 ? "" : "s"}` : `${shown.length} of ${certificates.length} shown`}
        </p>
        {filter !== "all" && (
          <button type="button" onClick={() => setFilter("all")} className="text-[12.5px] font-semibold text-tx-mute underline underline-offset-4 hover:text-white">
            Show all
          </button>
        )}
      </div>

      <ul className="flex flex-col gap-3">
        {shown.map(({ c }) => <CertCard key={c.id} c={c} now={now} />)}
      </ul>
      {shown.length === 0 && (
        <p className="card p-6 text-center text-[13px] text-tx-dim">Nothing in this group right now.</p>
      )}
    </div>
  );
}

/** "How it works" strip — kept short; the issue flow explains validation in full. */
export function SslHowItWorks() {
  const items = [
    { icon: "globe", t: "HTTP validation", d: "Your domain must point at the server and answer on port 80 while the certificate is issued." },
    { icon: "clock2", t: "One job at a time", d: "Requests wait their turn behind other work on the platform — a queued row shows exactly what it's behind." },
    { icon: "shield", t: "Weekly limit", d: "Let's Encrypt allows 5 identical certificates per domain per week, so we stop one short to keep you safe." },
    { icon: "refresh2", t: "Auto-renewal", d: "With auto-renew on, renewal starts 21 days before expiry. Expiry dates are read from the live certificate." },
  ];
  return (
    <section className="card p-4 sm:p-5">
      <p className="text-[11px] font-extrabold uppercase tracking-[0.2em] text-tx-faint">How certificates work here</p>
      <div className="mt-3 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {items.map((i) => (
          <div key={i.t} className="flex gap-3">
            <span className="grid h-9 w-9 flex-none place-items-center rounded-[11px] border border-rim-hi bg-well text-blue">
              <Icon name={i.icon} size={14} tone="inherit" />
            </span>
            <span className="min-w-0">
              <span className="block text-[13px] font-bold text-white">{i.t}</span>
              <span className="mt-0.5 block text-[12px] leading-relaxed text-tx-dim">{i.d}</span>
            </span>
          </div>
        ))}
      </div>
    </section>
  );
}

