import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { PageShell } from "@/components/nx/PageShell";
import { SslAurora } from "@/components/nx/SslAurora";
import { Icon } from "@/components/nx/Icon";
import { queueInfoFor } from "@/lib/ssl-queue";
import { CertificateHeroArt } from "@/components/customer/ssl/SslArt";
import { CertificateList, SslHowItWorks, type CertRow } from "@/components/customer/ssl/CertificateList";

export const dynamic = "force-dynamic";

export default async function SslPage() {
  const user = await requireUser();

  const [certificates, servers] = await Promise.all([
    db.sslCertificate.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" } }),
    db.server.findMany({ where: { userId: user.id }, select: { id: true, hostname: true, status: true } }),
  ]);

  const serverName = new Map(servers.map((s) => [s.id, s.hostname]));
  const myServerIds = new Set(servers.map((s) => s.id));

  // Queue visibility for unfinished requests — see lib/ssl-queue.ts.
  const inflight = certificates.filter((c) => c.status === "PENDING" || c.status === "ISSUING");
  const queueByCert = await queueInfoFor(inflight, myServerIds);

  const rows: CertRow[] = certificates.map((c) => ({
    id: c.id,
    domain: c.domain,
    status: c.status,
    issuer: c.issuer,
    autoRenew: c.autoRenew,
    serverId: c.serverId,
    serverName: c.serverId ? serverName.get(c.serverId) ?? null : null,
    issuedAt: c.issuedAt ? c.issuedAt.toISOString() : null,
    // The observed notAfter, or null. Nothing here is ever a computed guess.
    expiresAt: c.expiresAt ? c.expiresAt.toISOString() : null,
    lastError: c.lastError,
    queue: queueByCert.get(c.id) ?? null,
  }));

  // Certificate issuance needs a live, DNS-pointed server.
  const hasRunningServer = servers.some((s) => s.status === "RUNNING");

  return (
    <>
      {inflight.length > 0 && <AutoRefresh />}
      <SslAurora />
      {/* relative + z-1: SslAurora is a POSITIONED (fixed, z-0) layer and paints
          above ordinary static content unless the page gets its own layer. */}
      <div className="relative z-[1]">
        <PageShell
          eyebrow="NETWORK"
          title="SSL Certificates"
          sub="Free Let's Encrypt certificates for domains pointed at your servers — checked live before they're requested, and renewed automatically from 21 days before expiry."
          wisp={false}
          heroArt={<CertificateHeroArt />}
          action={
            rows.length > 0 && hasRunningServer ? (
              <Link href="/dashboard/ssl/new" className="btn-primary inline-flex items-center gap-2 whitespace-nowrap">
                <Icon name="plus" size={13} tone="inherit" /> New certificate
              </Link>
            ) : undefined
          }
        >
          {rows.length > 0 && !hasRunningServer && (
            <p className="card flex items-start gap-3 p-4 text-[13px] text-tx-dim">
              <Icon name="warncircle" size={15} tone="inherit" className="mt-0.5 text-amber" />
              <span>
                None of your servers is running, so new certificates can&apos;t be requested right now.{" "}
                <Link href="/dashboard/deploy" className="font-semibold text-tx-mute underline underline-offset-4 hover:text-white">
                  Deploy a server
                </Link>{" "}
                or start an existing one.
              </span>
            </p>
          )}
          <CertificateList certificates={rows} hasServers={hasRunningServer} nowMs={Date.now()} />
          <SslHowItWorks />
        </PageShell>
      </div>
    </>
  );
}

