import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageShell } from "@/components/nx/PageShell";
import { SslAurora } from "@/components/nx/SslAurora";
import { IssueFlow, type IssueServer } from "@/components/customer/ssl/IssueFlow";

export const dynamic = "force-dynamic";

export default async function NewCertificatePage({
  searchParams,
}: {
  searchParams: Promise<{ server?: string; domain?: string }>;
}) {
  const user = await requireUser();
  const sp = await searchParams;

  const servers = await db.server.findMany({
    where: { userId: user.id, status: "RUNNING" },
    orderBy: { createdAt: "desc" },
    select: { id: true, hostname: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } },
  });

  // Same resolution as connectionTarget() / checkSslReadiness: a dedicated IP, else the node's shared address.
  const options: IssueServer[] = servers.map((s) => ({
    id: s.id,
    hostname: s.hostname,
    address: s.dedicatedIp?.address ?? s.node?.publicIp ?? process.env.PUBLIC_IP ?? null,
    shared: !s.dedicatedIp,
  }));

  return (
    <>
      <SslAurora />
      <div className="relative z-[1]">
        <PageShell
          narrow
          eyebrow="NETWORK · SSL"
          title="New certificate"
          sub="Choose the server, enter the domain, and we'll check everything live before anything is requested — checks never use one of your weekly attempts."
