          <IssueFlow
            servers={options}
            initialServerId={options.some((o) => o.id === sp.server) ? sp.server! : options[0]?.id ?? ""}
            initialDomain={typeof sp.domain === "string" ? sp.domain.slice(0, 253) : ""}
          />
        </PageShell>
      </div>
    </>
  );
}

