"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { checkSslReadiness, requestCertificate } from "@/lib/actions-ssl";
import type { Readiness, CheckState } from "@/lib/ssl-status";
import { ValidationFlow } from "./SslArt";

/**
 * The issue flow for /dashboard/ssl/new.
 *
 * The old page was one inline form whose only guidance was a sentence about
 * HTTP-01. A request that was always going to fail (no A record, port 80
 * firewalled) still went to Let's Encrypt and spent one of the domain's five
 * weekly attempts. This flow runs `checkSslReadiness` first — a read-only DNS
 * lookup + one HTTP request to the domain + the same counters the request path
 * enforces — and explains each result with a concrete fix.
 *
 * The checks are advice, not a gate, except where the server would refuse anyway
 * (rate limit, duplicate, busy server): DNS can be correct and still propagating,
 * so a failed check asks for explicit confirmation instead of blocking.
 */

export type IssueServer = { id: string; hostname: string; address: string | null; shared: boolean };

const STATE_STYLE: Record<CheckState, { icon: string; col: string; label: string }> = {
  pass: { icon: "checkcircle", col: "var(--color-mint)", label: "Passed" },
  warn: { icon: "warntriangle", col: "var(--color-amber)", label: "Warning" },
  fail: { icon: "xcircle", col: "var(--color-rose)", label: "Failed" },
  skip: { icon: "dotgrey", col: "var(--color-tx-faint)", label: "Skipped" },
};

function StepHead({ n, title, done }: { n: number; title: string; done?: boolean }) {
  return (
    <div className="flex items-center gap-3">
      <span className={"grid h-7 w-7 flex-none place-items-center rounded-full text-[12px] font-extrabold " +
        (done ? "bg-[linear-gradient(135deg,var(--color-mint),var(--color-cyan))] text-[#01201a]"
              : "bg-[linear-gradient(135deg,var(--color-blue),var(--color-violet))] text-[#fff]")}>
        {done ? <Icon name="check" size={11} tone="inherit" /> : n}
      </span>
      <h2 className="text-[15px] font-extrabold tracking-[-0.01em] text-white">{title}</h2>
    </div>
  );
}

export function IssueFlow({
  servers, initialServerId, initialDomain,
}: { servers: IssueServer[]; initialServerId: string; initialDomain: string }) {
  const router = useRouter();
  const [serverId, setServerId] = useState(initialServerId);
  const [domain, setDomain] = useState(initialDomain);
  const [checked, setChecked] = useState<{ key: string; r: Readiness } | null>(null);
  const [checkErr, setCheckErr] = useState<string | null>(null);
  const [reqErr, setReqErr] = useState<string | null>(null);
  const [confirmAnyway, setConfirmAnyway] = useState(false);
  const [checking, startCheck] = useTransition();
  const [requesting, startReq] = useTransition();

  const server = servers.find((s) => s.id === serverId) ?? null;
  const clean = domain.trim().toLowerCase().replace(/^https?:\/\//, "").replace(/\/.*$/, "").replace(/\.$/, "");
  const key = `${serverId}|${clean}`;
  const current = checked && checked.key === key ? checked.r : null;
  const stale = !!checked && checked.key !== key;

  const runChecks = () =>
    startCheck(async () => {
      setCheckErr(null);
      setReqErr(null);
      setConfirmAnyway(false);
      const res = await checkSslReadiness(serverId, clean);
      if (res.error || !res.readiness) setCheckErr(res.error ?? "The checks could not run.");
      else setChecked({ key, r: res.readiness });
    });

  const submit = () =>
    startReq(async () => {
      setReqErr(null);
      const res = await requestCertificate(serverId, clean);
      if (res?.error) setReqErr(res.error);
      else if (res?.id) router.push(`/dashboard/ssl/${res.id}`);
    });

  if (servers.length === 0) {
    return (
      <section className="card flex flex-col items-start gap-3 p-6">
        <h2 className="text-[17px] font-extrabold text-white">You need a running server first</h2>
        <p className="max-w-[60ch] text-[13.5px] leading-relaxed text-tx-dim">
          Certificates are issued on the server your domain points at — it answers Let&apos;s Encrypt&apos;s
          validation request on port 80. Deploy one, or start a stopped server, then come back here.
        </p>
        <Link href="/dashboard/deploy" className="btn-primary inline-flex items-center gap-2">
          <Icon name="server" size={13} tone="inherit" /> Deploy a server
        </Link>
      </section>
    );
  }

  const canRequest = !!current && !current.hardStop && (!current.blocked || confirmAnyway);

  return (
    <div className="grid items-start gap-4 lg:grid-cols-[minmax(0,1fr)_340px]">
      <div className="flex min-w-0 flex-col gap-4">
        {/* 1 — server */}
        <section className="card flex flex-col gap-4 p-4 sm:p-5">
          <StepHead n={1} title="Choose the server" done={!!serverId} />
          <div role="radiogroup" aria-label="Server" className="grid gap-2.5 sm:grid-cols-2">
            {servers.map((s) => {
              const on = s.id === serverId;
              return (
                <button
                  key={s.id}
                  type="button"
                  role="radio"
                  aria-checked={on}
                  onClick={() => setServerId(s.id)}
                  className={"flex min-w-0 items-center gap-3 rounded-[13px] border p-3 text-left transition-colors " +
                    (on ? "border-[color-mix(in_srgb,var(--color-blue)_60%,transparent)] bg-[color-mix(in_srgb,var(--color-blue)_9%,var(--color-surface))]"
                        : "border-rim-hi bg-well hover:border-[color-mix(in_srgb,var(--color-blue)_35%,transparent)]")}
                >
                  <span className="grid h-9 w-9 flex-none place-items-center rounded-[11px] border border-rim-hi bg-surface text-cyan">
                    <Icon name="server" size={14} tone="inherit" />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-[13.5px] font-bold text-white">{s.hostname}</span>
                    <span className="block truncate text-[12px] text-tx-dim">
                      {s.address ?? "address pending"} · {s.shared ? "shared address" : "dedicated IP"}
                    </span>
                  </span>
                  <span aria-hidden className={"h-4 w-4 flex-none rounded-full border-2 " + (on ? "border-blue bg-[radial-gradient(circle,var(--color-blue)_45%,transparent_50%)]" : "border-rim-hi")} />
                </button>
              );
            })}
          </div>
        </section>

        {/* 2 — domain */}
        <section className="card flex flex-col gap-3 p-4 sm:p-5">
          <StepHead n={2} title="Enter the domain" done={!!current && !stale} />
          <form
            className="flex flex-col gap-2.5 sm:flex-row"
            onSubmit={(e) => { e.preventDefault(); if (clean.length >= 3) runChecks(); }}
          >
            <label htmlFor="ssl-domain" className="sr-only">Domain</label>
            <input
              id="ssl-domain"
              className="input min-w-0 flex-1"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              placeholder="app.example.com"
              autoComplete="off"
              autoCapitalize="none"
              spellCheck={false}
              inputMode="url"
            />
            <button type="submit" className="btn-ghost inline-flex items-center justify-center gap-2 px-4" disabled={checking || clean.length < 3}>
              <Icon name="search" size={13} tone="inherit" />
              {checking ? "Checking…" : current ? "Check again" : "Run checks"}
            </button>
          </form>
          <p className="text-[12px] text-tx-faint">
            One exact name per certificate, like <span className="text-tx-dim">www.example.com</span>. Wildcards
            (*.example.com) need DNS validation, which isn&apos;t available here.
          </p>
          {checkErr && <p role="alert" className="text-[13px] text-rose">{checkErr}</p>}
        </section>

        {/* 3 — checks */}
        <section className="card flex flex-col gap-3 p-4 sm:p-5" aria-live="polite" aria-busy={checking}>
          <StepHead n={3} title="Live checks" done={!!current && !current.blocked && !stale} />
          {!current ? (
            <p className="rounded-[12px] border border-dashed border-rim-hi bg-well p-4 text-[13px] text-tx-dim">
              {stale ? "You changed the server or domain — run the checks again." : "Run the checks to see whether this domain is ready. Nothing is requested yet."}
            </p>
          ) : (
            <ul className="flex flex-col divide-y divide-rim overflow-hidden rounded-[12px] border border-rim bg-well">
              {current.checks.map((c) => {
                const st = STATE_STYLE[c.state];
                return (
                  <li key={c.id} className="flex gap-3 p-3.5">
                    <span className="mt-0.5 flex-none" style={{ color: st.col }}>
                      <Icon name={st.icon} size={15} tone="inherit" />
                      <span className="sr-only">{st.label}:</span>
                    </span>
                    <span className="min-w-0 flex-1">
                      <span className="block text-[13px] font-bold text-white">{c.label}</span>
                      <span className="mt-0.5 block break-words text-[12.5px] leading-snug text-tx-dim">{c.detail}</span>
                      {c.fix && (
                        <span className="mt-1.5 flex gap-1.5 break-words text-[12.5px] leading-snug text-tx-body">
                          <span className="font-bold" style={{ color: st.col }}>Fix:</span> {c.fix}
                        </span>
                      )}
                    </span>
                  </li>
                );
              })}
            </ul>
          )}
        </section>

        {/* 4 — request */}
        <section className="card flex flex-col gap-3 p-4 sm:p-5">
          <StepHead n={4} title="Request the certificate" />
          {current?.hardStop ? (
            <p className="text-[13px] text-rose">{current.hardStop}</p>
          ) : current?.blocked ? (
            <label className="flex items-start gap-2.5 text-[13px] text-tx-body">
              <input type="checkbox" className="mt-0.5 h-4 w-4 accent-[var(--color-blue)]" checked={confirmAnyway} onChange={(e) => setConfirmAnyway(e.target.checked)} />
              <span>
                A check failed, so this request will very likely fail too — and a failed request still counts against
                this domain&apos;s weekly limit. Request anyway (for example, if you&apos;ve just changed DNS).
              </span>
            </label>
          ) : current ? (
            <p className="text-[13px] text-tx-dim">
              {current.warnings > 0 ? "Ready, with warnings worth a look above." : "Everything checks out."} Issuing usually takes about a minute once it&apos;s your turn in the queue.
            </p>
          ) : (
            <p className="text-[13px] text-tx-dim">Available once the checks have run.</p>
          )}
          <div className="flex flex-wrap items-center gap-3">
            <button type="button" className="btn-primary inline-flex items-center gap-2" disabled={!canRequest || requesting} onClick={submit}>
              <Icon name="lock" size={13} tone="inherit" />
              {requesting ? "Requesting…" : current?.blocked ? "Request anyway" : "Request certificate"}
            </button>
            {server && <span className="text-[12px] text-tx-faint">on {server.hostname}</span>}
          </div>
          {reqErr && <p role="alert" className="text-[13px] text-rose">{reqErr}</p>}
        </section>
      </div>

      <aside className="card flex flex-col gap-4 p-4 sm:p-5 lg:sticky lg:top-4">
        <div>
          <p className="text-[11px] font-extrabold uppercase tracking-[0.2em] text-tx-faint">How validation works</p>
          <p className="mt-1.5 text-[13px] leading-relaxed text-tx-dim">
            Let&apos;s Encrypt checks that you control the domain by making a normal web request to it.
          </p>
        </div>
        <div className="sm:[&_ol]:grid-cols-1 lg:[&_ol]:grid-cols-1">
          <ValidationFlow domain={clean || "your domain"} address={server?.address} />
        </div>
        <div className="rounded-[12px] border border-rim bg-well p-3 text-[12.5px] leading-relaxed text-tx-dim">
          <p className="font-bold text-white">Before you request</p>
          <ul className="mt-1 list-disc space-y-1 pl-4">
            <li>An A record for the exact name → {server?.address ?? "your server's IP"}.</li>
            <li>TCP port 80 open in the server&apos;s firewall.</li>
            <li>No proxy in front (e.g. Cloudflare&apos;s orange cloud) while issuing.</li>
          </ul>
        </div>
      </aside>
    </div>
  );
}

