// ---------------------------------------------------------------------------
// Renewal history (SSL_ISSUE jobs for one certificate)
// ---------------------------------------------------------------------------

export type HistoryJob = {
  status: string;
  /** `Job.step` — worker/ssl.ts writes the attempt's machine-readable outcome here. */
  step: string | null;
  error: string | null;
  renewal: boolean;
};

export type HistoryOutcome = {
  title: string;
  label: string;
  tone: "mint" | "amber" | "rose" | "blue" | "slate";
  /** Did this attempt reach Let's Encrypt (and so count against the weekly limit)? */
  countedAgainstLimit: boolean | null;
};

/**
 * What one attempt actually did. The step strings are the contract written by
 * worker/ssl.ts (SSL_STEP_*). Note "certificate issued" is also written when
 * certbot kept an existing, not-yet-due certificate, so it reads "Succeeded",
 * never a claim that a new certificate was minted.
 */
export function historyOutcome(j: HistoryJob): HistoryOutcome {
  const title = j.renewal ? "Renewal" : "First issue";
  if (j.status === "QUEUED") return { title, label: "Queued", tone: "blue", countedAgainstLimit: null };
  if (j.status === "RUNNING") return { title, label: "Running now", tone: "blue", countedAgainstLimit: null };
  switch (j.step) {
    case "certificate issued":
    case "paid certificate issued":
      return { title, label: "Succeeded", tone: "mint", countedAgainstLimit: true };
    case "simulated (sandbox)":
      return { title, label: "Simulated (sandbox)", tone: "slate", countedAgainstLimit: false };
    case "failed before contacting Let's Encrypt":
      return { title, label: "Failed before reaching Let's Encrypt", tone: "amber", countedAgainstLimit: false };
    case "failed at the certbot/ACME step":
      return { title, label: "Failed at Let's Encrypt", tone: "rose", countedAgainstLimit: true };
    case "failed at the paid-CA step":
      return { title, label: "Failed at the certificate authority", tone: "rose", countedAgainstLimit: true };
  }
  if (j.status === "FAILED") {
    return { title, label: /^Cancelled/.test(j.error ?? "") ? "Cancelled" : "Stopped before finishing", tone: "amber", countedAgainstLimit: null };
  }
  return { title, label: "Finished — no result recorded", tone: "slate", countedAgainstLimit: null };
}
EOF

