import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { SslAurora } from "@/components/nx/SslAurora";
import { Icon } from "@/components/nx/Icon";
import { queueInfoFor } from "@/lib/ssl-queue";
import { certView, explainSslError, historyOutcome } from "@/lib/ssl-status";
import { ExpiryRing, StateGlyph, StatusChip } from "@/components/customer/ssl/SslArt";
import { issuerName } from "@/components/customer/ssl/CertificateList";
import { QueueNote } from "@/components/customer/ssl/QueueNote";
import { CertificateActions, LiveServedCheck, TechDetails } from "@/components/customer/ssl/CertificateDetailBits";

export const dynamic = "force-dynamic";

type SslPayload = { certId?: string; renewal?: boolean };

function fmt(d: Date | null) {
  return d ? d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" }) : null;
}
function fmtTime(d: Date) {
  return `${d.toISOString().slice(0, 16).replace("T", " ")} UTC`;
}

const TONE: Record<string, string> = {
  mint: "var(--color-mint)", amber: "var(--color-amber)", rose: "var(--color-rose)", blue: "var(--color-blue)", slate: "var(--color-tx-faint)",
};

export default async function CertificatePage({ params }: { params: Promise<{ id: string }> }) {
  const user = await requireUser();
  const { id } = await params;

  // Scoped to the signed-in (or impersonated) customer: someone else's id is a 404, not a 403.
  const cert = await db.sslCertificate.findFirst({ where: { id, userId: user.id } });
  if (!cert) notFound();

  const [server, jobs, myServers] = await Promise.all([
    cert.serverId
      ? db.server.findFirst({ where: { id: cert.serverId, userId: user.id }, select: { id: true, hostname: true, status: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } } })
      : Promise.resolve(null),
    db.job.findMany({
      where: { type: "SSL_ISSUE", payload: { path: ["certId"], equals: cert.id } },
      orderBy: { createdAt: "desc" },
      take: 25,
      select: { id: true, status: true, step: true, error: true, createdAt: true, finishedAt: true, payload: true },
    }),
    db.server.findMany({ where: { userId: user.id }, select: { id: true } }),
  ]);

  const inflight = cert.status === "PENDING" || cert.status === "ISSUING";
  const queue = inflight ? (await queueInfoFor([cert], new Set(myServers.map((s) => s.id)))).get(cert.id) ?? null : null;
  const now = Date.now();
  const v = certView({
    status: cert.status,
    issuedAt: cert.issuedAt?.toISOString() ?? null,
    expiresAt: cert.expiresAt?.toISOString() ?? null,
    lastError: cert.lastError,
    autoRenew: cert.autoRenew,
    queueState: queue?.state ?? null,
  }, now);
  const why = inflight ? null : explainSslError(cert.lastError, cert.domain);
  const address = server ? server.dedicatedIp?.address ?? server.node?.publicIp ?? null : null;

  const facts: { k: string; v: React.ReactNode }[] = [
    { k: "Covers", v: <span className="break-all">{cert.domain}<span className="ml-2 text-tx-faint">· single name</span></span> },
    { k: "Issued by", v: issuerName(cert.issuer) },
    { k: "Validation", v: "HTTP (port 80)" },
    { k: "Issued", v: fmt(cert.issuedAt) ?? <span className="text-tx-faint">not yet</span> },
    { k: "Expires", v: cert.expiresAt ? <span suppressHydrationWarning>{fmt(cert.expiresAt)}</span> : <span className="text-tx-faint">not observed yet</span> },
    {
      k: "Server",
      v: server ? (
        <Link href={`/dashboard/servers/${server.id}`} className="font-semibold text-tx-mute underline underline-offset-4 hover:text-white">
          {server.hostname}
        </Link>
      ) : cert.serverId ? <span className="text-amber">deleted</span> : <span className="text-tx-faint">none</span>,
    },
    ...(address ? [{ k: "Address", v: `${address}${server?.dedicatedIp ? " (dedicated)" : " (shared)"}` }] : []),
    {
      k: "Renewal",
      v: !cert.autoRenew
        ? <span className="text-amber">Off — it won&apos;t be replaced before it expires</span>
        : v.renewWindowOpensAt
          ? <span suppressHydrationWarning>Automatic, from {fmt(new Date(v.renewWindowOpensAt))}</span>
          : "Automatic, from 21 days before expiry",
    },
  ];

  return (
    <>
      {inflight && <AutoRefresh />}
      <SslAurora />
      <div className="relative z-[1] mx-auto flex w-full max-w-[1180px] flex-col gap-4">
        <nav aria-label="Breadcrumb" className="text-[12.5px] text-tx-faint">
          <Link href="/dashboard/ssl" className="hover:text-white">SSL Certificates</Link>
          <span aria-hidden className="mx-2">/</span>
          <span className="text-tx-dim">{cert.domain}</span>
        </nav>

        {/* Header object: glyph, domain, status, expiry ring. */}
        <header className="card relative flex flex-col gap-5 overflow-hidden p-5 sm:flex-row sm:items-center sm:p-6">
          <span aria-hidden className="pointer-events-none absolute inset-y-0 right-0 w-1/2 opacity-60"
                style={{ background: "radial-gradient(60% 80% at 80% 50%, color-mix(in srgb, var(--color-blue) 16%, transparent), transparent 70%)" }} />
          <div className="relative flex min-w-0 flex-1 items-start gap-4">
            <StateGlyph state={v.state} size={52} />
            <div className="min-w-0">
              <span className="text-[11px] font-extrabold uppercase tracking-[0.22em] text-[var(--color-magenta)]">Certificate</span>
              <h1 className="mt-0.5 break-all text-[24px] font-extrabold leading-tight tracking-[-0.03em] text-white sm:text-[28px]">{cert.domain}</h1>
              <div className="mt-2 flex flex-wrap items-center gap-2.5">
                <StatusChip view={v} />
                <span className="text-[12.5px] text-tx-dim">{issuerName(cert.issuer)}{server ? ` · ${server.hostname}` : ""}</span>
              </div>
              {inflight && <QueueNote q={queue} />}
            </div>
          </div>
          <div className="relative flex items-center gap-4 self-start sm:self-auto">
            <ExpiryRing view={v} uid={`ring-${cert.id}`} />
          </div>
        </header>

        {why && (
          <section className="card flex flex-col gap-3 p-5" style={{ borderColor: `color-mix(in srgb, ${TONE[v.tone === "violet" ? "blue" : v.tone]} 45%, transparent)` }}
                   aria-labelledby="ssl-why">
            <div className="flex items-start gap-3">
              <span className="mt-0.5" style={{ color: TONE[v.tone === "rose" ? "rose" : "amber"] }}>
                <Icon name={v.tone === "rose" ? "xcircle" : "warntriangle"} size={16} tone="inherit" />
              </span>
              <div className="min-w-0">
                <h2 id="ssl-why" className="text-[15.5px] font-extrabold text-white">{why.title}</h2>
                <p className="mt-1 text-[13px] leading-relaxed text-tx-dim">{why.why}</p>
              </div>
            </div>
            <ol className="ml-1 flex flex-col gap-2">
              {why.fixes.map((f, i) => (
                <li key={i} className="flex gap-3 text-[13px] leading-relaxed text-tx-body">
                  <span className="grid h-5 w-5 flex-none place-items-center rounded-full border border-rim-hi bg-well text-[11px] font-bold text-tx-mute">{i + 1}</span>
                  <span className="min-w-0 break-words">{f}</span>
                </li>
              ))}
            </ol>
            <TechDetails text={cert.lastError ?? ""} />
          </section>
        )}

        <div className="grid items-start gap-4 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
          <section className="card flex flex-col gap-3 p-5" aria-labelledby="ssl-facts">
            <h2 id="ssl-facts" className="text-[15px] font-extrabold text-white">Certificate</h2>
            <dl className="divide-y divide-rim">
              {facts.map((f) => (
                <div key={f.k} className="grid grid-cols-[110px_minmax(0,1fr)] gap-3 py-2.5 text-[13px]">
                  <dt className="text-tx-faint">{f.k}</dt>
                  <dd className="min-w-0 text-tx-body">{f.v}</dd>
                </div>
              ))}
            </dl>
            <p className="text-[11.5px] leading-relaxed text-tx-faint">
              Dates are read from the certificate itself — at issuance, then from what {cert.domain} serves on port 443.
            </p>
          </section>

          <LiveServedCheck domain={cert.domain} auto={["ACTIVE", "EXPIRED"].includes(cert.status)} />
        </div>

        <section className="card flex flex-col gap-3 p-5" aria-labelledby="ssl-history">
          <div className="flex flex-wrap items-baseline justify-between gap-2">
            <h2 id="ssl-history" className="text-[15px] font-extrabold text-white">Issue &amp; renewal history</h2>
            <span className="text-[12px] text-tx-faint">Most recent first · up to 25 attempts</span>
          </div>
          {jobs.length === 0 ? (
            <p className="text-[13px] text-tx-dim">No attempts are on record for this certificate.</p>
          ) : (
            <ol className="relative flex flex-col">
              {jobs.map((j, i) => {
                const o = historyOutcome({ status: j.status, step: j.step, error: j.error, renewal: !!((j.payload ?? {}) as SslPayload).renewal });
                return (
                  <li key={j.id} className="relative flex gap-3.5 pb-4 last:pb-0">
                    {i < jobs.length - 1 && <span aria-hidden className="absolute left-[6px] top-4 h-full w-px bg-rim" />}
                    <span aria-hidden className="relative mt-1 h-[13px] w-[13px] flex-none rounded-full border-2"
                          style={{ borderColor: TONE[o.tone], background: `color-mix(in srgb, ${TONE[o.tone]} 25%, transparent)` }} />
                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-baseline gap-x-2.5 gap-y-0.5">
                        <span className="text-[13px] font-bold text-white">{o.title}</span>
                        <span className="text-[12.5px] font-semibold" style={{ color: TONE[o.tone] }}>{o.label}</span>
                        <span className="text-[12px] text-tx-faint">{fmtTime(j.createdAt)}</span>
                      </div>
                      {o.countedAgainstLimit === false && (
                        <p className="mt-0.5 text-[12px] text-tx-faint">Didn&apos;t count against the weekly limit.</p>
                      )}
                      {j.error && <p className="mt-0.5 break-words text-[12px] text-tx-dim">{j.error.slice(0, 240)}</p>}
                    </div>
                  </li>
                );
              })}
            </ol>
          )}
        </section>

        <CertificateActions
          cert={{ id: cert.id, domain: cert.domain, status: cert.status, autoRenew: cert.autoRenew, hasServer: !!server }}
          issuingNow={cert.status === "ISSUING" && queue?.state === "running"}
          retryHelps={why?.retryHelps ?? true}
        />
      </div>
    </>
  );
}

