"use client";

import { useRouter } from "next/navigation";
import { useCallback, useEffect, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { deleteCertificate, renewCertificate, toggleAutoRenew } from "@/lib/actions-ssl";

/** The raw worker/certbot text, kept one click away rather than shown as the headline. */
export function TechDetails({ text }: { text: string }) {
  if (!text) return null;
  return (
    <details className="group rounded-[11px] border border-rim bg-well">
      <summary className="cursor-pointer select-none list-none px-3.5 py-2.5 text-[12.5px] font-semibold text-tx-mute hover:text-white">
        <span className="inline-block transition-transform group-open:rotate-90" aria-hidden>›</span> Technical details
      </summary>
      <pre className="max-h-64 overflow-auto whitespace-pre-wrap break-words border-t border-rim px-3.5 py-3 font-mono text-[11.5px] leading-relaxed text-tx-dim">{text}</pre>
    </details>
  );
}

type Served = {
  ok: true; subject: string | null; issuer: string | null; altNames: string[]; validFrom: string; validTo: string;
  daysToExpiry: number; expired: boolean; valid: boolean; validationError: string | null; protocol: string | null;
  chain: { subject: string | null; issuer: string | null; validTo: string }[];
};

/**
 * A live TLS read of what the domain is serving RIGHT NOW, through the same
 * read-only checker the public SSL tool uses (/api/tools/ssl-checker: vetted
 * public IP, SNI = domain, 5s timeout). This is where the chain and served SANs
 * come from — the platform does not store them, so this panel never pretends
 * to know them without looking.
 */
export function LiveServedCheck({ domain, auto }: { domain: string; auto: boolean }) {
  const [state, setState] = useState<{ loading: boolean; data: Served | null; error: string | null; at: string | null }>({ loading: false, data: null, error: null, at: null });

  const run = useCallback(async () => {
    setState((s) => ({ ...s, loading: true, error: null }));
    try {
      const res = await fetch("/api/tools/ssl-checker", {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ host: domain }),
      });
      const j = await res.json().catch(() => ({}));
      if (!res.ok || !j.ok) setState({ loading: false, data: null, error: j.error ?? `Check failed (HTTP ${res.status}).`, at: new Date().toISOString() });
      else setState({ loading: false, data: j as Served, error: null, at: new Date().toISOString() });
    } catch {
      setState({ loading: false, data: null, error: "The check couldn't run — try again.", at: new Date().toISOString() });
    }
  }, [domain]);

  useEffect(() => { if (auto) void run(); }, [auto, run]);

  const d = state.data;
  const covers = d ? d.altNames.some((n) => n === domain || (n.startsWith("*.") && domain.endsWith(n.slice(1)) && domain.split(".").length === n.split(".").length)) : false;
  // Leaf first from the checker; show root → leaf, the way people read a chain.
  const chain = d ? [...d.chain].reverse() : [];

  return (
    <section className="card flex flex-col gap-3 p-5" aria-labelledby="ssl-live" aria-busy={state.loading}>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h2 id="ssl-live" className="flex items-center gap-2 text-[15px] font-extrabold text-white">
          <span className="relative flex h-2 w-2">
            <span className="absolute inline-flex h-full w-full rounded-full bg-cyan opacity-60 motion-safe:animate-ping" />
            <span className="relative inline-flex h-2 w-2 rounded-full bg-cyan" />
          </span>
          Live from https://{domain}
        </h2>
        <button type="button" onClick={run} disabled={state.loading} className="btn-ghost inline-flex items-center gap-1.5 px-3 py-1.5 text-[12.5px]">
          <Icon name="refresh" size={11} tone="inherit" className={state.loading ? "motion-safe:animate-spin" : ""} />
          {state.loading ? "Checking…" : d || state.error ? "Check again" : "Check now"}
        </button>
      </div>

      {!d && !state.error && !state.loading && (
        <p className="text-[13px] text-tx-dim">Reads the certificate your domain is serving on port 443 — its chain, the names it covers, and whether browsers trust it.</p>
      )}
      {state.loading && !d && <div className="h-28 animate-pulse rounded-[12px] bg-well" />}
      {state.error && (
        <p className="rounded-[11px] border border-rim bg-well p-3 text-[13px] text-tx-dim">
          <span className="font-semibold text-amber">Nothing readable on port 443.</span> {state.error}
        </p>
      )}

      {d && (
        <>
          <div className="flex flex-wrap gap-2">
            <Pill ok={d.valid && !d.expired} yes="Trusted by browsers" no={d.expired ? "Expired" : `Not trusted${d.validationError ? ` (${d.validationError})` : ""}`} />
            <Pill ok={covers} yes="Name matches" no="Name doesn't match" />
            {d.protocol && <span className="rounded-full border border-rim-hi bg-well px-2.5 py-[3px] text-[12px] font-semibold text-tx-mute">{d.protocol}</span>}
          </div>

          <div>
            <p className="mb-2 text-[11px] font-extrabold uppercase tracking-[0.18em] text-tx-faint">Chain</p>
            <ol className="flex flex-col gap-1.5">
              {chain.map((c, i) => (
                <li key={i} className="flex items-center gap-2.5" style={{ paddingLeft: i * 14 }}>
                  <span className="grid h-7 w-7 flex-none place-items-center rounded-[9px] border border-rim-hi bg-well"
                        style={{ color: i === chain.length - 1 ? "var(--color-cyan)" : i === 0 ? "var(--color-violet)" : "var(--color-blue)" }}>
                    <Icon name={i === chain.length - 1 ? "lock" : "certbadge"} size={11} tone="inherit" />
                  </span>
                  <span className="min-w-0">
                    <span className="block truncate text-[13px] font-semibold text-white">{c.subject ?? "(unnamed)"}</span>
                    <span className="block text-[11.5px] text-tx-faint">
                      {i === chain.length - 1 ? "Your certificate" : i === 0 ? "Root" : "Intermediate"} · until {c.validTo.slice(0, 11).trim() || c.validTo}
                    </span>
                  </span>
                </li>
              ))}
            </ol>
          </div>

          <div>
            <p className="mb-1.5 text-[11px] font-extrabold uppercase tracking-[0.18em] text-tx-faint">Names covered (SANs)</p>
            <div className="flex flex-wrap gap-1.5">
              {d.altNames.length === 0 ? <span className="text-[12.5px] text-tx-dim">none listed</span> : d.altNames.map((n) => (
                <span key={n} className={"rounded-[8px] border px-2 py-[2px] font-mono text-[12px] " + (n === domain ? "border-[color-mix(in_srgb,var(--color-cyan)_45%,transparent)] text-cyan" : "border-rim-hi text-tx-dim")}>{n}</span>
              ))}
            </div>
          </div>
          <p suppressHydrationWarning className="text-[11.5px] text-tx-faint">
            Served certificate valid {new Date(d.validFrom).toISOString().slice(0, 10)} → {new Date(d.validTo).toISOString().slice(0, 10)}
            {state.at ? ` · checked ${new Date(state.at).toISOString().slice(11, 16)} UTC` : ""}
          </p>
        </>
      )}
    </section>
  );
}

function Pill({ ok, yes, no }: { ok: boolean; yes: string; no: string }) {
  const col = ok ? "var(--color-mint)" : "var(--color-rose)";
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full border px-2.5 py-[3px] text-[12px] font-bold"
          style={{ color: col, borderColor: `color-mix(in srgb, ${col} 40%, transparent)`, background: `color-mix(in srgb, ${col} 10%, transparent)` }}>
      <Icon name={ok ? "checkcircle" : "xcircle"} size={10} tone="inherit" /> {ok ? yes : no}
    </span>
  );
}

/** Auto-renew, Renew now and Delete — same server actions, same confirmations as before. */
export function CertificateActions({
  cert, issuingNow, retryHelps,
}: {
  cert: { id: string; domain: string; status: string; autoRenew: boolean; hasServer: boolean };
  issuingNow: boolean;
  retryHelps: boolean;
}) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const canRenew = ["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status) && cert.hasServer;

  const run = (fn: () => Promise<{ error?: string }>, confirmMsg: string | null, after?: () => void) => {
    if (confirmMsg && !window.confirm(confirmMsg)) return;
    start(async () => {
      setError(null);
      setNote(null);
      const res = await fn();
      if (res?.error) setError(res.error);
      else after?.();
    });
  };

  return (
    <section className="card flex flex-col gap-4 p-5" aria-labelledby="ssl-manage">
      <h2 id="ssl-manage" className="text-[15px] font-extrabold text-white">Manage</h2>
      <div className="grid gap-3 md:grid-cols-3">
        <div className="flex flex-col gap-2 rounded-[13px] border border-rim bg-well p-4">
          <div className="flex items-center justify-between gap-3">
            <span className="text-[13.5px] font-bold text-white">Auto-renew</span>
            <button
              type="button" role="switch" aria-checked={cert.autoRenew} aria-label={`Auto-renew for ${cert.domain}`}
              disabled={pending} onClick={() => run(() => toggleAutoRenew(cert.id), null)}
              className={"nx-inline relative inline-flex h-6 w-11 flex-none items-center rounded-full border transition-colors " +
                (cert.autoRenew ? "border-transparent bg-[linear-gradient(90deg,var(--color-blue),var(--color-violet))]" : "border-rim-hi bg-surface") + (pending ? " opacity-60" : "")}
            >
              <span className={"inline-block h-[18px] w-[18px] rounded-full bg-[#fff] shadow transition-transform " + (cert.autoRenew ? "translate-x-[22px]" : "translate-x-[3px]")} />
            </button>
          </div>
          <p className="text-[12.5px] leading-relaxed text-tx-dim">
            {cert.autoRenew ? "Renews on its own from 21 days before expiry." : "Off — you'll be warned before expiry, but nothing is renewed."}
          </p>
        </div>

        <div className="flex flex-col gap-2 rounded-[13px] border border-rim bg-well p-4">
          <span className="text-[13.5px] font-bold text-white">Renew now</span>
          <p className="text-[12.5px] leading-relaxed text-tx-dim">
            {!cert.hasServer ? "Not possible — the server it lived on no longer exists."
              : !canRenew ? "Available once the current attempt finishes."
              : retryHelps ? "Reissue immediately. Each attempt counts toward the weekly limit of 5."
              : "Fix the issue above first — reissuing alone won't change it."}
          </p>
          <button
            type="button" className="btn-ghost mt-auto inline-flex items-center justify-center gap-1.5 px-3 py-2 text-[13px]"
            disabled={pending || !canRenew}
            onClick={() => run(() => renewCertificate(cert.id),
              `Reissue the certificate for "${cert.domain}" now? Let's Encrypt allows only 5 identical certificates per week, so use this sparingly.`,
              () => { setNote("Renewal queued — this page updates on its own."); router.refresh(); })}
          >
            <Icon name="refresh" size={12} tone="inherit" /> Renew now
          </button>
        </div>

        <div className="flex flex-col gap-2 rounded-[13px] border border-[color-mix(in_srgb,var(--color-rose)_30%,transparent)] bg-well p-4">
          <span className="text-[13.5px] font-bold text-white">Delete record</span>
          <p className="text-[12.5px] leading-relaxed text-tx-dim">
            Removes it from your account. Files already on your server are left in place.
          </p>
          <button
            type="button" className="btn-danger mt-auto inline-flex items-center justify-center gap-1.5 px-3 py-2 text-[13px]"
            disabled={pending || issuingNow}
            title={issuingNow ? "The certificate is being issued right now" : undefined}
            onClick={() => run(() => deleteCertificate(cert.id),
              `Delete the certificate for "${cert.domain}"? This removes it from your account.`,
              () => router.push("/dashboard/ssl"))}
          >
            <Icon name="trash" size={12} tone="inherit" /> Delete
          </button>
        </div>
      </div>
      {note && <p role="status" className="text-[13px] text-mint">{note}</p>}
      {error && <p role="alert" className="text-[13px] text-rose">{error}</p>}
    </section>
  );
}

