/* ---- explainSslError ------------------------------------------------------ */

test("explanations match the real worker and certbot strings", () => {
  const cases: [string, string][] = [
    ["This certificate's server was deleted, so it cannot be renewed. Delete this record, or issue a new certificate on a server that exists.", "server-gone"],
    ["Automatic renewal is paused until 2026-10-09 10:00 UTC: 4 certificate requests…", "renewal-paused"],
    ["Certificate issuance is switched off on this server (ENABLE_REAL_SSL is not set), so…", "issuance-off"],
    ["certbot failed: Detail: DNS problem: NXDOMAIN looking up A for blog.example.com", "dns"],
    ["certbot failed: CAA record for example.com prevents issuance", "caa"],
    ["certbot failed: Timeout during connect (likely firewall problem)", "port80-blocked"],
    ["certbot failed: Invalid response from http://x/.well-known/acme-challenge/abc: 404", "wrong-target"],
    ["certbot failed: Could not bind TCP port 80 because it is already in use", "port80-busy"],
    ["certbot install failed: E: Unable to locate package certbot", "certbot-install"],
    ["SSH connect timed out after 15s", "server-unreachable"],
    ["The certificate exists, but nothing is serving it for https://api.example.com — port 443 refused", "not-installed"],
    ["Port 443 on x is serving a certificate issued for a different hostname, so…", "wrong-name"],
    ["The certificate served for x covers the right hostname but is NOT trusted by browsers (x)", "untrusted"],
    ["…expires 2026-12-01 — it is NOT the certificate we issued, which expires…", "cdn"],
    ["No issuance job ever ran for this request — it was queued 20 minutes ago", "stalled"],
    ["Renewal failed: certbot failed: too many certificates (5) already issued for this exact set", "rate-limit"],
    ["something nobody anticipated", "unknown"],
  ];
  for (const [raw, kind] of cases) assert.equal(explainSslError(raw, "example.com")?.kind, kind, raw);
});

test("an SSH timeout is not mistaken for a port-80 firewall problem", () => {
  assert.equal(explainSslError("SSH connect timed out after 15s")?.kind, "server-unreachable");
});

test("no error, no explanation", () => {
  assert.equal(explainSslError(null), null);
});

test("every explanation offers at least one concrete fix", () => {
  for (const raw of ["NXDOMAIN", "CAA record", "Could not bind", "xyz"]) {
    assert.ok((explainSslError(raw)?.fixes.length ?? 0) > 0);
  }
});

/* ---- readinessVerdict ----------------------------------------------------- */

const facts = (over: Partial<ReadinessFacts> = {}): ReadinessFacts => ({
  domain: "app.example.com", domainValid: true, serverAddress: "198.51.100.7", sharedAddress: false,
  a: ["198.51.100.7"], aaaa: [], dnsError: null, http: { reached: true, status: 404 },
  attempts: { total: 0, leRelevant: 0, resumesAt: null }, maxLeAttempts: 4, maxTotalAttempts: 6,
  serverBusy: false, existing: null, ...over,
});
const byId = (r: ReturnType<typeof readinessVerdict>, id: string) => r.checks.find((c) => c.id === id);

test("a correctly pointed domain with port 80 open passes cleanly", () => {
  const r = readinessVerdict(facts());
  assert.equal(r.blocked, false);
  assert.equal(r.warnings, 0);
  assert.equal(r.hardStop, null);
  assert.equal(byId(r, "port80")?.state, "pass", "a 404 still proves port 80 answers");
});

test("no A record fails with a fix naming the server's address", () => {
  const r = readinessVerdict(facts({ a: null, dnsError: "no record", http: null }));
  assert.equal(byId(r, "dns")?.state, "fail");
  assert.match(byId(r, "dns")!.fix!, /198\.51\.100\.7/);
  assert.equal(r.blocked, true);
  assert.equal(r.hardStop, null, "DNS problems are advice, not a server-side refusal");
});

test("pointing at a different IP fails", () => {
  const r = readinessVerdict(facts({ a: ["203.0.113.9"] }));
  assert.equal(byId(r, "target")?.state, "fail");
});

test("an AAAA record and a shared address are warnings, not failures", () => {
  const r = readinessVerdict(facts({ aaaa: ["2001:db8::1"], sharedAddress: true }));
  assert.equal(byId(r, "ipv6")?.state, "warn");
  assert.equal(byId(r, "target")?.state, "warn");
  assert.equal(r.blocked, false);
  assert.equal(r.warnings, 2);
});

test("port 80 unreachable fails", () => {
  const r = readinessVerdict(facts({ http: { reached: false, error: "connection refused" } }));
  assert.equal(byId(r, "port80")?.state, "fail");
});

test("the weekly limit is a hard stop, mirroring requestCertificate", () => {
  const r = readinessVerdict(facts({ attempts: { total: 4, leRelevant: 4, resumesAt: "2026-10-09T10:00:00.000Z" } }));
  assert.match(r.hardStop!, /2026-10-09 10:00 UTC/);
  const r2 = readinessVerdict(facts({ attempts: { total: 6, leRelevant: 0, resumesAt: null } }));
  assert.ok(r2.hardStop);
});

test("duplicate and busy-server refusals are hard stops", () => {
  assert.ok(readinessVerdict(facts({ existing: "active" })).hardStop);
  assert.ok(readinessVerdict(facts({ existing: "inflight" })).hardStop);
  assert.ok(readinessVerdict(facts({ serverBusy: true })).hardStop);
});

test("an invalid domain skips the network checks", () => {
  const r = readinessVerdict(facts({ domain: "*.example.com", domainValid: false, a: null, http: null }));
  assert.equal(byId(r, "name")?.state, "fail");
  assert.equal(byId(r, "dns")?.state, "skip");
});

test("the limit constants in the readiness action are the ones requestCertificate enforces", () => {
  const src = readFileSync(join(__dirname, "..", "lib", "actions-ssl.ts"), "utf8");
  const action = src.slice(src.indexOf("export async function checkSslReadiness"));
  assert.match(action, /maxLeAttempts: MAX_LE_ATTEMPTS_PER_WINDOW/);
  assert.match(action, /maxTotalAttempts: MAX_TOTAL_ATTEMPTS_PER_WINDOW/);
  assert.match(action, /issueAttemptsFor\(clean\)/);
  assert.doesNotMatch(action, /db\.job\.create|sslCertificate\.(create|update|delete)/, "checks must be read-only");
});

test("RENEW_LEAD_DAYS matches the worker's RENEW_LEAD_MS", () => {
  const src = readFileSync(join(__dirname, "..", "worker", "ssl.ts"), "utf8");
  assert.match(src, new RegExp(`const RENEW_LEAD_MS = ${RENEW_LEAD_DAYS} \\* 86400_000`));
});

/* ---- historyOutcome ------------------------------------------------------- */

test("history labels follow the worker's step contract", () => {
  assert.equal(historyOutcome({ status: "DONE", step: "certificate issued", error: null, renewal: true }).label, "Succeeded");
  const pre = historyOutcome({ status: "DONE", step: "failed before contacting Let's Encrypt", error: null, renewal: false });
  assert.equal(pre.countedAgainstLimit, false);
  assert.equal(historyOutcome({ status: "DONE", step: "failed at the certbot/ACME step", error: null, renewal: true }).countedAgainstLimit, true);
  assert.equal(historyOutcome({ status: "FAILED", step: null, error: "Cancelled — the customer deleted…", renewal: false }).label, "Cancelled");
  assert.equal(historyOutcome({ status: "QUEUED", step: null, error: null, renewal: false }).label, "Queued");
});

test("the step strings used here exist in worker/ssl.ts / lib/ssl-verify.ts", () => {
  const w = readFileSync(join(__dirname, "..", "worker", "ssl.ts"), "utf8") + readFileSync(join(__dirname, "..", "lib", "ssl-verify.ts"), "utf8");
  for (const s of ["certificate issued", "failed at the certbot/ACME step", "paid certificate issued", "failed at the paid-CA step", "failed before contacting Let's Encrypt", "simulated (sandbox)"]) {
    assert.ok(w.includes(`"${s}"`), s);
  }
});

