S=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/sslov; cp $S/../ssl-tokens.json $S/; cat > $S/shot.mjs <<'EOF'
// usage: node shot.mjs <prefix> <tokenKey> <paths...>
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
const require = createRequire("/opt/nxeon/node_modules/");
const { chromium } = require("playwright");
const [, , prefix, tokenKey, ...paths] = process.argv;
const tok = JSON.parse(readFileSync(new URL("./ssl-tokens.json", import.meta.url)));
const BASE = process.env.BASE ?? "http://localhost:3077";
const OUT = "/root/agent-notes/ssl-overhaul";
const ONLY = process.env.ONLY; // e.g. "desktop-dark"
const browser = await chromium.launch({ args: ["--disable-gpu"] });
const views = [
  { tag: "desktop", width: 1440, height: 1000, mobile: false },
  { tag: "mobile", width: 390, height: 844, mobile: true },
];
for (const p of paths) {
  const resolved = p.replace("{certId}", tok.certId);
  for (const v of views) for (const theme of ["dark", "light"]) {
    if (ONLY && !ONLY.split(",").includes(`${v.tag}-${theme}`)) continue;
    const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, deviceScaleFactor: 2, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme, reducedMotion: "reduce" });
    await ctx.addCookies([{ name: "nx_agt_ssl", value: tok[tokenKey], url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
    const page = await ctx.newPage();
    await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); } catch {} }, theme);
    const errs = [];
    page.on("pageerror", (e) => errs.push(String(e)));
    page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
    await page.goto(BASE + resolved, { waitUntil: "networkidle", timeout: 180000 }).catch((e) => errs.push("goto " + e));
    if (process.env.ACT) { try { await eval(process.env.ACT)(page); } catch (e) { errs.push("act " + e); } }
    await page.waitForTimeout(1200);
    const slug = resolved.replace(tok.certId, "id").replace(/\?.*$/, "").replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "");
    const name = `${OUT}/${prefix}-${slug}-${v.tag}-${theme}.png`;
    await page.screenshot({ path: name, fullPage: true });
    console.log(name, errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
    await ctx.close();
  }
}
await browser.close();
EOF
cd $S && timeout 600 node shot.mjs r1 full /dashboard/ssl "/dashboard/ssl/{certId}" 2>&1 | tail -8

